NAME = 'ACV: A Conservative Version'
BOOK = 'I Kings'

CHAPTERS = {
    1: {
        1: 'David kralj pa je bil že star in prileten, in pokrivali so ga z odejami, a se ni ogrel.',
        2: 'Zato so mu rekli služabniki njegovi: Poišče naj se za gospoda mojega, kralja, mlada devica, in naj stoji pri kralju in mu bodi strežnica ter naj spava v naročju njegovem, da se ogreje gospod moj, kralj.',
        3: 'In iskali so lepe mladenke po vseh krajih Izraelovih, in najdejo Abisago Sunamljanko ter jo pripeljejo h kralju.',
        4: 'Mladenka pa je bila zelo lepa, in postala je strežnica kralju in mu je služila; a kralj je ni spoznal.',
        5: 'Tedaj se je Adonija, sin Hagitin, povzdignil, rekoč: Jaz bom kraljeval! In oskrbi si voz in konj in petdeset mož, ki naj bi tekali pred njim.',
        6: 'In oče njegov ga nikdar ni užalil, da bi mu bil rekel: Zakaj si storil tako? Bil pa je tudi zelo lepe postave mož, in rojen je bil po Absalomu.',
        7: 'In posvetoval se je z Joabom, sinom Zervijinim, in z duhovnikom Abiatarjem, in ona sta mu pomagala, hodeč za njim.',
        8: 'Ali Zadok duhovnik in Benaja, sin Jojadov, in Natan prorok in Simej in Rej in vojščaki, ki so bili Davidovi, niso bili pri Adoniju.',
        9: 'In Adonija pokolje ovac in volov in pitancev pri kamenu Zoheletu, ki je tik studenca Rogela, in povabi vse brate svoje, sinove kraljeve, in vse može Judove, kraljeve služabnike;',
        10: 'toda Natana proroka in Benaja in vojščakov in Salomona, brata svojega, ni povabil.',
        11: 'Tedaj govori Natan Batsebi, materi Salomonovi, rekoč: Nisi li slišala, da je zakraljeval Adonija, sin Hagitin, in David, gospod naš, ne ve za to?',
        12: 'Sedaj pa pridi, daj, da ti svetujem, da bi rešila življenje sebi in sinu svojemu Salomonu.',
        13: 'Pojdi in stopi h kralju Davidu in mu reci: Nisi li, gospod moj, kralj, prisegel meni, dekli svoji, in rekel: Salomon, sin tvoj, bo kraljeval za menoj in on bo sedel na prestolu mojem? Zakaj torej kraljuje Adonija?',
        14: 'Glej, ko boš tam še govorila s kraljem, pridem tudi jaz noter za teboj in potrdim besede tvoje.',
        15: 'In Batseba pride h kralju v čumnato. Kralj pa je bil zelo star, in Abisaga Sunamljanka je stregla kralju.',
        16: 'In Batseba se pripogne in stori poklon kralju. In kralj vpraša: Kaj želiš?',
        17: 'Ona mu pa reče: Gospod moj, ti si prisegel pri Gospodu, Bogu svojem, dekli svoji: Salomon, sin tvoj, bo kraljeval za menoj in on bo sedel na prestolu mojem.',
        18: 'In sedaj, glej, Adonija kraljuje, in ti, gospod moj, kralj, ne veš tega.',
        19: 'In je zaklal obilo volov in pitancev in ovec ter je povabil vse sinove kraljeve in Abiatarja, duhovnika, in Joaba, poveljnika vojske, a Salomona, hlapca tvojega, ni povabil.',
        20: 'Ti pa, gospod moj, kralj – oči vsega Izraela se ozirajo v te, da jim poveš, kdo bo sedel na prestolu gospoda mojega, kralja, za teboj.',
        21: 'Sicer se zgodi, ko bo legel gospod moj, kralj, k očetom svojim, da bodo šteli mene in sina mojega Salomona kakor dva grešnika.',
        22: 'In glej, ko še govori s kraljem, pride Natan prorok.',
        23: 'In naznanijo kralju, rekoč: Glej, Natan prorok. In ko stopi pred kralja, se pokloni pred kraljem z obrazom do tal.',
        24: 'In Natan reče: Gospod moj, kralj, si li ti rekel: Adonija bo kraljeval za menoj in on bo sedel na prestolu mojem?',
        25: 'Kajti danes je šel doli in zaklal obilo volov in pitancev in ovac ter je povabil vse sinove kraljeve in poveljnike vojske in Abiatarja duhovnika; in glej, jedo in pijejo pred njim ter govore: Živel kralj Adonija!',
        26: 'Mene pa, mene hlapca tvojega, in Zadoka duhovnika in Benaja, sina Jojadovega, in hlapca tvojega Salomona ni povabil.',
        27: 'Se li je ta stvar napravila po gospodu mojem, kralju? Pa nisi oznanil hlapcem svojim, kdo bo sedel na prestolu gospoda mojega, kralja, za njim?',
        28: 'Nato kralj odgovori in reče: Pokličite mi Batsebo. In ona stopi pred kralja in se postavi pred njim.',
        29: 'In kralj priseže in veli: Kakor res živi Gospod, ki je rešil dušo mojo iz vseh nadlog:',
        30: 'kakor sem ti prisegel pri Gospodu, Bogu Izraelovem, rekši: Salomon, sin tvoj, bo kraljeval za menoj in on bo sedel na prestolu mojem namesto mene, res, tako storim danes.',
        31: 'Tedaj se pripogne Batseba z obrazom do tal in stori kralju poklon ter reče: Naj živi gospod moj, kralj David, vekomaj!',
        32: 'In kralj David veli: Pokličite mi Zadoka duhovnika in Natana proroka in Benaja, sina Jojadovega. In pridejo pred kralja.',
        33: 'In kralj jim veli: Vzemite s seboj hlapce gospoda svojega in dajte Salomonu, sinu mojemu, jezditi na mojem mezgu ter ga peljite doli h Gihonu.',
        34: 'In tam naj ga pomazili Zadok duhovnik in Natan prorok za kralja Izraelu, in trobite na trobento ter recite: Naj živi kralj Salomon!',
        35: 'Potem pojdete gori za njim, in on pride sem ter sede na moj prestol, zakaj kraljeval bo na mojem mestu, in jaz sem ukazal zanj, da bodi vojvoda Izraelu in Judi.',
        36: 'In Benaja, sin Jojadov, odgovori kralju in reče: Amen! Gospod, Bog gospoda mojega, kralja, naj reče istotako!',
        37: 'Kakor je bil Gospod z gospodom mojim, kraljem, tako bodi s Salomonom in poveličaj mu prestol bolj, nego ga je poveličal gospodu mojemu, kralju Davidu.',
        38: 'Zadok duhovnik torej in Natan prorok in Benaja, sin Jojadov, in Keretejci in Peletejci gredo doli ter posade Salomona na mezga kralja Davida in ga peljejo h Gihonu.',
        39: 'In Zadok duhovnik vzame rog z oljem iz Šatora in pomazili Salomona. In zatrobijo na trobento, in vse ljudstvo kliče: Naj živi kralj Salomon!',
        40: 'In vse ljudstvo je šlo gori v mesto za njim, in množica je godla na piščali in se veselila z velikim veseljem, da je zemlja odmevala od njih glasu.',
        41: 'In Adonija in vsi gostje, ki so bili ž njim, zaslišijo to, ko so končali pojedino. In ko Joab čuje trobente glas, reče: Čemu je ta šum v mestu kakor ob vstaji?',
        42: 'Ko še govori, glej, prispeje Jonatan, sin Abiatarja duhovnika, in Adonija reče: Pridi sem, kajti vrl si mož in neseš dobro poročilo.',
        43: 'In Jonatan odgovori in reče Adoniju: V resnici je gospod naš, kralj David, postavil Salomona za kralja!',
        44: 'In kralj je ž njim poslal Zadoka duhovnika in Natana proroka in Benaja, sina Jojadovega, in Keretejce in Peletejce, in so ga posadili na kraljevega mezga,',
        45: 'in Zadok duhovnik in Natan prorok sta ga pomazilila za kralja pri Gihonu. In prišli so gori odondod z veseljem, da se je mesto razburilo. To je šum, ki ste ga slišali.',
        46: 'In Salomon je že tudi zasedel prestol kraljestva.',
        47: 'In vrhutega so prišli kraljevi hlapci blagoslavljat gospoda našega, kralja Davida, govoreč: Bog tvoj naj stori ime Salomonovo bolj sloveče nego tvoje ime in poveliča prestol njegov bolj nego tvoj prestol. In kralj se je poklonil Bogu na postelji svoji.',
        48: 'In kralj je tudi rekel takole: Hvaljen bodi Gospod, Bog Izraelov, ki mi je dal danes sedečega na prestolu mojem, da moje oči to še vidijo.',
        49: 'In vsi gostje Adonijevi se prestrašijo ter vstanejo in odidejo vsak svojim potom.',
        50: 'Adonija pa, boječ se Salomona, vstane in odide ter se oprime oltarjevih rogov.',
        51: 'In povedali so Salomonu, rekoč: Glej, Adonija se boji kralja Salomona, in glej, drži se, rogov oltarja in govori: Naj mi priseže danes kralj Salomon, da ne ubije hlapca svojega z mečem.',
        52: 'In Salomon veli: Ako se izkaže vrlega moža, mu las ne pade z glave na tla; ako se pa hudoba najde pri njem, mora umreti.',
        53: 'Pošlje torej Salomon in ga pripeljejo od oltarja. In pride ter se pokloni kralju Salomonu, in Salomon mu reče: Pojdi v hišo svojo!',
    },
    2: {
        1: 'Davidu pa so se bližali dnevi, da umrje. In zapove sinu svojemu Salomonu, rekoč:',
        2: 'Jaz odhajam po poti vsega zemeljskega; bodi torej. močan in kaži se moža',
        3: 'in strezi na službo Gospodu, Bogu svojemu, da hodiš po potih njegovih, da izpolnjuješ postave in zapovedi in sodbe njegove in pričevanja njegova, po tem, kar je pisano v zakonu Mojzesovem, da bi imel prospeh v vsem, kar počneš in kamorkoli se obrneš;',
        4: 'da bi Gospod utrdil besedo svojo, ki jo je govoril zame, rekoč: Bodo li pazili sinovi tvoji na pot svojo, da hodijo pred menoj v resnici z vsem srcem svojim in z vso dušo svojo, ne bo ti zmanjkalo (je dejal) moža za prestol Izraelov.',
        5: 'Veš pa, kar mi je storil Joab, sin Zervijin, namreč kar je storil dvema poveljnikoma vojsk Izraelovih, Abnerju, sinu Nerovemu, in Amasu, sinu Jeterjevemu, ki ju je ubil in prelil kri kakor v vojni ob času miru in si okrvavil z zvijačno prelito krvjo pas okoli ledij in obuvalo na nogah.',
        6: 'Stóri torej ž njim po modrosti svoji in ne pústi sivi glavi njegovi, da gre v grob v miru.',
        7: 'Sinovom Barzilaja Gileadčana pa izkazuj milost ter naj bodo med tistimi, ki jedo pri mizi tvoji, kajti tako so prišli k meni, ko sem bežal pred Absalomom, bratom tvojim.',
        8: 'Glej tudi, izročen ti je Simej, sin Gerov, Benjaminec iz Bahurima, ki me je preklinjal s strašnim preklinjanjem v dan, ko sem šel v Mahanaim; ali prišel mi je naproti doli k Jordanu, in prisegel sem mu pri Gospodu, rekoč: Ne umorim te z mečem.',
        9: 'Sedaj ga torej ne imej za nedolžnega, zakaj moder si mož in vedel boš, kako naj ž njim ravnaš, in spraviš sivo glavo njegovo v grob s krvjo.',
        10: 'In legel je David k očetom svojim in je bil pokopan v mestu Davidovem.',
        11: 'Dni pa, kar jih je David kraljeval Izraelu, je bilo štirideset let: sedem let je kraljeval v Hebronu, triintrideset let pa v Jeruzalemu.',
        12: 'In Salomon je zasedel prestol Davida, očeta svojega, in kraljestvo njegovo je bilo dobro utrjeno.',
        13: 'Tedaj pride Adonija, sin Hagitin, k Batsebi, materi Salomonovi. In ona vpraša: Je li tvoj prihod miren? On odgovori: Miren.',
        14: 'Dalje reče: Imam s teboj nekaj govoriti. Ona veli: Govóri!',
        15: 'In reče: Veš, da je bilo kraljestvo moje in da je ves Izrael obrnil proti meni obličje svoje, da bodem kralj; toda kraljestvo je šlo mimo mene ter pripadlo mojemu bratu, kajti njemu je bilo določeno od Gospoda.',
        16: 'In zdaj imam eno prošnjo do tebe, ne zavrni me. Ona mu veli: Govóri!',
        17: 'On pa reče: Govóri, prosim, s kraljem Salomonom, kajti on ne zavrne tebe, da naj mi da Abisago Sunamljanko za ženo.',
        18: 'In Batseba reče: Dobro; hočem s kraljem govoriti zastran tebe.',
        19: 'Gre torej Batseba h kralju Salomonu govorit ž njim zastran Adonija. In vstane kralj ter ji pride naproti in se ji pokloni, potem sede na svoj prestol in veli postaviti prestol za mater kraljevo, in ona mu sede ob desnici.',
        20: 'Tedaj reče: Majhno prošnjo imam do tebe, ne zavrni me! In kralj ji reče: Prosi, mati moja, kajti ne zavrnem te.',
        21: 'Ona reče: Naj se da Abisaga Sunamljanka bratu tvojemu Adoniju za ženo.',
        22: 'In kralj Salomon odgovori ter reče materi svoji: Zakaj pa prosiš Abisage Sunamljanke za Adonija? Prosi zanj še tudi kraljestva – kajti on je moj starejši brat – in za njega in za Abiatarja duhovnika in za Joaba, sina Zervije.',
        23: 'Nato priseže kralj Salomon pri Gospodu, rekoč: To naj mi stori Gospod in to naj pridene, če ni govoril Adonija te besede zoper življenje svoje!',
        24: 'Zdaj torej, kakor res živi Gospod, ki me je potrdil in me posadil na očeta mojega Davida prestol in ki mi je ustanovil hišo, kakor je bil obljubil: gotovo danes mora Adonija umreti.',
        25: 'In pošlje kralj Salomon Benaja, sina Jojadovega, in ta ga je udaril, da je umrl.',
        26: 'Abiatarju duhovniku pa je rekel kralj: Pojdi v Anatot na njive svoje, zakaj vreden si smrti, ali nočem te danes umoriti, ker si nosil skrinjo Gospoda Jehove pred Davidom, očetom mojim, in ker si vse stiske trpel ž njim, kadar je on bil v stiskah.',
        27: 'In Salomon je odstavil Abiatarja, da ni bil več duhovnik Gospodu; da se izpolni beseda Gospodova, ki jo je govoril za hišo Elijevo v Silu.',
        28: 'In glas o tem je prišel do Joaba, zakaj Joab se je odvrnil za Adonijem, dasi se za Absalomom ni bil odvrnil. In pobegne Joab v šator Gospodov ter se oprime rogov oltarja.',
        29: 'In sporoče kralju Salomonu: Joab je zbežal v šator Gospodov, in glej, je pri oltarju. Tedaj pošlje Salomon Benaja, sina Jojadovega, in veli: Pojdi, udari ga!',
        30: 'In pride Benaja v šator Gospodov ter mu reče: Tako pravi kralj: Pojdi ven! On odgovori: Nikar, kajti tu hočem umreti. In sporoči Benaja besedo kralju, rekoč: Tako je rekel Joab in tako mi je odgovoril.',
        31: 'In veli mu kralj: Stóri mu, kakor je rekel, in udari ga ter ga pokoplji, da odpraviš kri, ki jo je Joab prelil brez razloga, od mene in od hiše očeta mojega.',
        32: 'In Gospod povrne kri na glavo njegovo, ker je udaril dva moža, pravičnejša in boljša, nego je bil sam, in ju je umoril z mečem, in oče moj, David, ni vedel za to: Abnerja, sina Nerovega, poveljnika vojske Izraelove, in Amasa, sina Jeterjevega, poveljnika vojske Judove.',
        33: 'Tako se povrne njiju kri na glavo Joabovo in na glavo zaroda njegovega vekomaj; ali Davidu in zarodu njegovemu in hiši njegovi in prestolu njegovemu bodi mir vekomaj od Gospoda!',
        34: 'Šel je torej gori Benaja, sin Jojadov, in ga je udaril in usmrtil; in pokopan je bil v svoji hiši v puščavi.',
        35: 'In kralj je postavil Benaja, sina Jojadovega, namesto njega nad vojsko, in Zadoka duhovnika je kralj postavil namesto Abiatarja.',
        36: 'Pošlje tudi kralj in pokliče Simeja ter mu veli: Sezidaj si hišo v Jeruzalemu in tu prebivaj ter ne hodi odtod ne tja, ne sem.',
        37: 'Kateri dan namreč pojdeš ven in preideš potok Kidron, vedi za gotovo, da moraš umreti; tvoja kri pride na tvojo glavo.',
        38: 'In Simej reče kralju: Dobra je ta beseda; kakor je velel gospod moj, kralj, tako bo storil hlapec tvoj. In Simej je prebival precej časa v Jeruzalemu.',
        39: 'Prigodi se pa po treh letih, da sta Simeju utekla dva hlapca k Ahisu, sinu Maakovemu, h kralju v Gatu. In sporoče Simeju, rekoč: Glej, hlapca tvoja sta v Gatu.',
        40: 'In vstane Simej ter osedla osla ter gre v Gat k Ahisu, da poišče svoja hlapca; odide torej in pripelje hlapca svoja iz Gata.',
        41: 'In naznanijo Salomonu, da je šel Simej iz Jeruzalema v Gat in se zopet vrnil.',
        42: 'In kralj pošlje ter pokliče Simeja in mu reče: Te li nisem zaprisegel pri Gospodu in te resno posvaril, rekoč: Gotovo vedi, da moraš umreti, kateri dan greš ven in pojdeš sem ali tja? In si mi dejal: Dobra je beseda, ki sem jo slišal.',
        43: 'Zakaj nisi torej izpolnil prisege Gospodove in zapovedi, ki sem ti jo ukazal?',
        44: 'Še reče Salomon Simeju: Ti veš za vso hudobnost, katere si je v svesti srce tvoje, ki si jo storil Davidu, očetu mojemu; zato Gospod povrne hudobnost tvojo tebi na glavo.',
        45: 'A kralj Salomon bo blagoslovljen in prestol Davidov bo utrjen pred Gospodom za vekomaj.',
        46: 'In kralj ukaže Benaju, Jojadovemu sinu, in ta gre ven ter ga udari, da umrje. In kraljestvo je bilo utrjeno v roki Salomonovi.',
    },
    3: {
        1: 'In Salomon je sklenil svaštvo s Faraonom, egiptovskim kraljem, vzemši hčer Faraonovo; in pripeljal jo je v mesto Davidovo, dokler ni dozidal hiše svoje in hiše Gospodove in zidu okoli Jeruzalema.',
        2: 'Ali ljudstvo je darovalo na višavah, ker ni bilo hiše sezidane imenu Gospodovem do teh dni.',
        3: 'In Salomon je ljubil Gospoda živeč po postavah Davida, očeta svojega, samo da je daroval in kadilo žgal na višavah.',
        4: 'Šel pa je Salomon v Gibeon, da bi ondi daroval, kajti to je bila velika višava; tisoč žgalnih daritev je daroval Salomon na ondotnem oltarju.',
        5: 'V Gibeonu se je Gospod prikazal Salomonu v sanjah po noči; in Bog je dejal: Prosi, kaj naj ti dam.',
        6: 'In Salomon reče: Ti si izkazal hlapcu svojemu Davidu, očetu mojemu, veliko milost, po tem, da je živel pred obličjem tvojim v resnici, v pravičnosti in poštenosti srca s teboj; in si mu ohranil to milost veliko, da si mu dal sina, da bi sedel na prestolu njegovem, kakor se danes vidi.',
        7: 'In sedaj, Gospod, Bog moj, si storil hlapca svojega za kralja namesto Davida, očeta mojega, jaz pa sem majhen deček, ne vem, kako hoditi ven in kako hoditi noter.',
        8: 'In hlapec tvoj je sredi ljudstva tvojega, ki si ga izvolil, ki je ljudstvo veliko in se ne more prešteti, ne popisati zavoljo množine.',
        9: 'Daj torej hlapcu svojemu razumno srce, da more soditi ljudstvo tvoje in razpoznavati dobro in zlo; kajti kdo je zmožen soditi temu množnemu ljudstvu tvojemu?',
        10: 'In dobra je bila ta beseda v očeh Gospodovih, da je Salomon prosil take reči.',
        11: 'In Bog mu reče: Ker si prosil te reči in nisi prosil sebi dolgega življenja, tudi ne bogastva zase, niti smrti svojih sovražnikov, marveč si prosil zase razumnosti, da znaš zasliševati pravde:',
        12: 'glej, storil sem po besedi tvoji: dal sem ti srce modro in razumno, da ni bilo tebi enakega pred teboj in tudi za teboj enak ne vstane.',
        13: 'Pa tudi česar nisi prosil, sem ti dal, bogastva in slave, da ne bode tebi enakega med kralji vse tvoje žive dni.',
        14: 'In ako boš hodil po mojih potih, izpolnjujoč moje postave in zapovedi, kakor je hodil oče tvoj David, podaljšam tvoje dni.',
        15: 'In Salomon se prebudi, in glej, sanje so bile; in pride v Jeruzalem ter se postavi pred skrinjo zaveze Gospodove in daruje žgalne in mirovne daritve in napravi gostovanje vsem svojim hlapcem.',
        16: 'Tedaj sta prišli dve ženski, nečistnici, h kralju in stopili predenj.',
        17: 'In prva reče: Prosim, gospod moj, jaz in ta žena prebivava v eni hiši, in porodila sem pri njej v hiši.',
        18: 'In tretji dan po mojem porodu je porodila tudi ona; in bili sva skupaj ter ni bilo tujca z nama v hiši, sami dve sva bili v hiši.',
        19: 'In te žene sin je umrl po noči, ker ga je poležala.',
        20: 'In vstane opolnoči in vzame sina mojega od moje strani, ko je spala dekla tvoja, ter ga položi v naročje svoje, svojega mrtvega sina pa položi meni v naročje.',
        21: 'In ko vstanem proti jutru, da bi podojila sina svojega, glej, mrtev je bil; ali ko ga bolj skrbno pogledam za jutra, glej, ni bil moj sin, ki sem ga bila porodila.',
        22: 'In druga žena reče: Ni tako, ampak moj sin je živ, in tvoj sin je mrtev. Ta pa odvrne: Nikar, ampak mrtvi je tvoj, živi pa moj. Tako sta se prepirali pred kraljem.',
        23: 'Tedaj reče kralj: Ta pravi: Ta je moj sin, ki živi, in mrtvi je tvoj; in druga pravi: Nikar, ampak tvoj sin je mrtev, moj pa živi.',
        24: 'Veli kralj: Prinesite mi meč! In prineso pred kralja meč.',
        25: 'Kralj pa veli: Razdelite živo dete na dvoje in dajte tej polovico ter polovico oni!',
        26: 'Tedaj izpregovori žena, katere je bilo živo dete, kajti njeno srce se je genilo nad njenim otrokom, in reče kralju: Prosim, gospod moj, dajte ji živo dete in nikar ga ne usmrtite! Druga pa reče: Ne bodi ne moje, ne tvoje, razdeli naj se!',
        27: 'Tedaj odgovori kralj in veli: Dajte oni živo dete, nikar ga ne umorite! ona je mati njegova.',
        28: 'In slišal je ves Izrael sodbo, ki jo je razsodil kralj, in bali so se kralja, kajti videli so, da je modrost Božja v njem, da bi delil pravico.',
    },
    4: {
        1: 'In kralj Salomon je kraljeval vsemu Izraelu.',
        2: 'In ti so knezi, ki jih je imel: Azarija, sin Zadokov, duhovnik;',
        3: 'Elihoref in Ahija, sinova Sisova, sta bila pisarja; Josafat, sin Ahiludov, je bil deželni letopisec;',
        4: 'in Benaja, sin Jojadov, je bil nad vojsko, in Zadok in Abiatar sta bila duhovnika;',
        5: 'Azarija pa, sin Natanov, je bil nad uradniki, in Zabud, sin Natanov, je bil prvi dvorjan, kraljev prijatelj;',
        6: 'in Ahisar je bil nad dvorcem in Adoniram, sin Abdov, je bil nad davščinami.',
        7: 'In Salomon je imel dvanajst uradnikov nad vsem Izraelom, ki so oskrbovali kralja in družino njegovo z živežem: vsak je imel oskrbovati po en mesec v letu.',
        8: 'In ta so njih imena: Benhur na Efraimskem gorovju,',
        9: 'Bendeker v Makazu in v Saalbimu in Betsemesu in Elon-bethananu;',
        10: 'Benhesed v Arubotu, njemu je pripadalo Soko in vsa pokrajina Heferska;',
        11: 'Ben-abinadab na vsem hribovju Dorskem; on je imel Tafato, hčer Salomonovo, za ženo;',
        12: 'Baana, sin Ahiludov, v Taanahu in Megidu in v vsem Betseanu, ki je poleg Zaretana pod Jezreelom, od Betseana do Abel-mehole, tja daleč nasproti Jokmeamu;',
        13: 'Bengeber v Ramot-gileadu; njemu so pripadali trgi Jaira, sina Manaseja, ki so v Gileadu, njegov je bil kraj Argob, ki je v Basanu, šestdeset velikih mest z okopi in bronastimi zapahi;',
        14: 'Ahinadab, sin Idov, v Mahanaimu;',
        15: 'Ahimaaz v Neftaliju; on je tudi vzel Basemato, hčer Salomonovo, za ženo;',
        16: 'Baana, sin Husajev, v Aserju in Alotu;',
        17: 'Josafat, sin Parnahov, v Isaharju;',
        18: 'Simej, sin Elov, v Benjaminu;',
        19: 'Geber, sin Urijev, v Gileadski pokrajini, v deželi Sihona, kralja Amorejcev, in Oga, kralja v Basanu; in on je bil edini uradnik v pokrajini.',
        20: 'Juda in Izrael sta bila mnogoštevilna kakor pesek, ki ga je ob morju obilo; jedli so in pili ter se veselili.',
        21: 'In Salomon je gospodoval vsem kraljestvom od velereke do dežele Filistejcev in do egiptovske meje: prinašali so mu darila in služili Salomonu vse dni življenja njegovega.',
        22: 'In Salomonov potrebni živež na dan je bil: trideset meric bele moke in šestdeset meric druge moke,',
        23: 'deset pitanih volov in dvajset pašnih volov in sto ovac razen jelenov, srn in srnjakov in pitane perutnine.',
        24: 'Kajti imel je gospostvo nad vsemi pokrajinami na tej strani velereke, od Tifsaha do Gaze, nad vsemi kralji tostran reke; in imel je mir na vseh straneh naokoli.',
        25: 'In Juda in Izrael je prebival brez skrbi, vsak pod svojo trto in pod svojo smokvo, od Dana do Bersebe vse dni Salomonove.',
        26: 'In Salomon je imel štirideset tisoč jasli za vprežne konje in dvanajst tisoč konj za ježo.',
        27: 'In tisti uradniki so oskrbovali živež kralju Salomonu in vsem, ki so jedli pri kraljevi mizi, vsak v svojem mesecu, in so pazili, da ni ničesar primanjkalo.',
        28: 'Tudi ječmen in slamo za konje in mezge so spravljali na mesto, kjer je bilo treba, vsak po svojem naročilu.',
        29: 'In Bog je dal Salomonu modrosti in razumnosti jako obilo in širokosti srca kakor peska, ki je ob morskem bregu.',
        30: 'In večja je bila modrost Salomonova nego modrost vseh sinov na Jutrovem in vsa modrost Egipčanov.',
        31: 'Kajti modrejši je bil nego vsi ljudje, nego Etan Ezrahovec in Heman in Kalkol in Darda, sinovi Maholovi, in glas imena njegovega je šel po vseh narodih naokrog.',
        32: 'In govoril je tri tisoč pregovorov in pesmi njegovih je bilo tisoč in pet.',
        33: 'In govoril je o drevju, od cedre, ki je na Libanonu, do izopa, ki raste iz stene; govoril je tudi, o živini in o pticah in o laznini in o ribah.',
        34: 'In prihajali so izmed vseh ljudstev poslušat modrost Salomonovo, od vseh kraljev zemlje, ki so začuli o modrosti njegovi.',
    },
    5: {
        1: 'In Hiram, kralj tirski, je poslal služabnike svoje k Salomonu, zakaj slišal je bil, da so ga pomazilili za kralja namesto očeta njegovega; Hiram je namreč ljubil Davida vse dni.',
        2: 'In Salomon pošlje k Hiramu sporočit:',
        3: 'Ti veš, da ni mogel David, oče moj, zgraditi hiše imenu Gospoda, Boga svojega, spričo sosedov, ki so ga zapletali v vojne, dokler jih ni položil Gospod pod stopala nog njegovih.',
        4: 'Sedaj pa mi je dal Gospod, Bog moj, mir vseokrog; nobenega ni nasprotnika, ne hude prigodbe.',
        5: 'Glej torej, zgraditi nameravam hišo imenu Gospoda, Boga svojega, kakor je Gospod govoril Davidu, očetu mojemu, rekoč: Sin tvoj, ki ga posadim na prestol tvoj na tvoje mesto, sezida hišo imenu mojemu.',
        6: 'Zdaj torej ukaži, da mi nasekajo ceder z Libanona, in hlapci moji bodo s hlapci tvojimi, tudi plačilo ti dam za hlapce tvoje, kakršnokoli boš zahteval; saj veš, da ga ni med nami, ki bi znal sekati les kakor Sidonci.',
        7: 'In ko je slišal Hiram besede Salomonove, se silno razveseli ter reče: Hvaljen bodi danes Gospod, ki je dal Davidu modrega sina nad tem velikim ljudstvom!',
        8: 'In Hiram pošlje Salomonu sporočit: Slišal sem, kar si mi sporočil. Storil bom vso voljo tvojo glede cedrovega in cipresovega lesa.',
        9: 'Hlapci moji ga bodo spravljali z Libanona doli k morju, in zložim ga v splave, da pojde po morju do mesta, ki mi ga določiš; in tam ga dam razvezati, in ti si ga odpraviš. Ti pa izpolniš voljo mojo, da boš dajal živeža moji družini.',
        10: 'Tako je dal Hiram Salomonu cedrovega in cipresovega lesa po vsej volji njegovi.',
        11: 'Salomon pa je dajal Hiramu po dvajset tisoč meric pšenice v živež njegovi družini in po dvajset meric čistega olja; toliko je dal Salomon Hiramu vsako leto.',
        12: 'In Gospod je dal Salomonu modrost, kakor mu je obljubil; in bil je mir med Hiramom in Salomonom, in oba sta sklenila zavezo.',
        13: 'In kralj Salomon je vzel davek od vsega Izraela, in davek je bil trideset tisoč mož.',
        14: 'In pošiljal jih je na Libanon, po deset tisoč vsak mesec, menoma: mesec dni so bili na Libanonu in dva meseca doma. Adoniram pa je bil nad temi robotniki.',
        15: 'In Salomon jih je imel sedemdeset tisoč, ki so nosili bremena, in osemdeset tisoč njih, ki so sekali v gorah,',
        16: 'razen višjih uradnikov, ki so nadzorovali delo, tri tisoč in tristo; ti so gospodovali ljudstvu, ki je opravljalo delo.',
        17: 'In kralj je ukazal, in pripravili so velikih in dragih kamenov, obsekanih kamenov za podstavo hiši.',
        18: 'In obdelovali so jih Salomonovi stavbarji in Hiramovi stavbarji in Gebaljani; in pripravljali so les in kamenje za stavbo hiše.',
    },
    6: {
        1: 'In bilo je v štiristo in osemdesetem letu po izhodu sinov Izraelovih iz Egiptovske dežele, v četrtem letu Salomonovega kraljevanja Izraelu, v mesecu Zivu, ki je drugi mesec, da je zidal hišo Gospodu.',
        2: 'In hiša, ki jo je gradil kralj Salomon Gospodu, je bila šestdeset komolcev dolga, dvajset komolcev široka in trideset komolcev visoka.',
        3: 'In veža pred templjevo dvorano je bila dvajset komolcev dolga, skladno s širjavo hiše, in deset komolcev široka spredaj pred hišo.',
        4: 'In hiši je naredil okna, široka znotraj in ozka zunaj.',
        5: 'In ob zidovju hiše, sporedno s hišnimi stenami, pri dvorani in pri govorišču, je zgradil tristropen prizidek in v njem stranske sobe kroginkrog:',
        6: 'spodnje stropje je bilo široko pet komolcev, srednje šest komolcev in tretje sedem komolcev široko; kajti na zunanji strani hišnega zida je napravil odstavke, da ne bi bila bruna vtaknjena v hišni zid.',
        7: 'In ko so gradili hišo, so jo skladali iz kamenov, popolnoma obsekanih v kamenarnici, da ni bilo slišati kladiva, ne sekire, ne kakršnegakoli železnega orodja v hiši, ko so jo gradili.',
        8: 'Vrata do spodnjih obstranskih sob so bila na desni strani hiše, in po zavitih stopnicah se je hodilo v srednje sobe in iz srednjih v tretje.',
        9: 'In zidal je hišo in jo dokončal; in prekril je hišo z bruni in deskami iz cedrovine.',
        10: 'In prizidek je zgradil ob vsej hiši, vsako nadstropje po pet komolcev visoko, in cedrovo brunovje jih je vezalo s hišo.',
        11: 'In beseda Gospodova je prišla Salomonu, govoreč:',
        12: 'Zastran te hiše, ki jo gradiš –: ako boš živel po mojih postavah in izvrševal sodbe moje in pazil na vse moje zapovedi, da se po njih ravnaš, utrdim besedo svojo s teboj, ki sem jo govoril tvojemu očetu Davidu.',
        13: 'In prebival bom med sinovi Izraelovimi in ne zapustim ljudstva svojega Izraela.',
        14: 'In Salomon je zidal hišo in jo dozidal.',
        15: 'In obložil je hišne stene odznotraj s cedrovimi deskami; od tal hiše do stropnih brun jih je znotraj opažil z lesom, tudi tla hiše je pokril s cipresovimi deskami.',
        16: 'In pregradil je dvajset komolcev od zadnje strani hiše znotraj s cedrovo steno od tal do stropa, da bodi to notri v hiši za govorišče ali Najsvetejše.',
        17: 'Hiša pa, to je templjeva dvorana spredaj, je bila štirideset komolcev dolga.',
        18: 'In po hišnih stenah odznotraj je bila cedrovina in na njej izrezano bučkasto sadje in razvito cvetje; vse je bila cedrovina, kamena se ni nič videlo.',
        19: 'In govorišče znotraj v hiši je pripravil, da tam postavi skrinjo zaveze Gospodove.',
        20: 'Bilo je pa govorišče znotraj dvajset komolcev dolgo, dvajset široko in dvajset visoko, in obložil ga je s čistim zlatom; tudi oltar iz cedrovine je obložil ž njim.',
        21: 'In Salomon je prevlekel hišo znotraj s čistim zlatom; in potegnil je zlate verižice pred govoriščem, ko ga je prevlekel z zlatom.',
        22: 'In vso hišo je prevlekel z zlatom, vso hišo popolnoma; tudi ves oltar, ki je bil ob govorišču, je prevlekel z zlatom.',
        23: 'In v govorišču je naredil dva keruba iz oljkovega lesa, deset komolcev visoka.',
        24: 'In pet komolcev je imela ena perut keruba in pet komolcev druga perut: od kraja ene peruti do konca druge peruti je bilo deset komolcev.',
        25: 'In drugi kerub je imel deset komolcev; oba keruba sta bila ene mere in ene oblike.',
        26: 'Višava enega keruba je bila deset komolcev in takisto drugega keruba.',
        27: 'In postavil je keruba v notranjo hišo, in peruti kerubov so bile razprostrte, da se je perut enega dotikala tega zidu in perut drugega keruba onega zidu, a sredi hiše sta se dotikali druga druge.',
        28: 'In prevlekel je keruba z zlatom.',
        29: 'In dal je narediti po vseh stenah kroginkrog izrezane podobe kerubov in palm in razvitega cvetja, znotraj in zunaj.',
        30: 'In tla hiše je obložil z zlatom znotraj in zunaj.',
        31: 'In za vhod v govorišče je napravil vrata iz oljkovega lesa, naddurje s podboji je bilo dolgo petino zidu.',
        32: 'In dve durnici sta bili iz oljkovega lesa, in naredil je na njiju izrezljane kerube in palme in razvito cvetje in ju prevlekel z zlatom, in raztegnil je zlato tudi po kerubih in po palmah.',
        33: 'Enako je napravil za vhod v templjevo dvorano podboje iz oljkovega lesa, za četrtino zida;',
        34: 'in dvoje duri iz cipresovine, dve durnici enih duri sta se pregibali, tudi dve durnici drugih duri sta se pregibali.',
        35: 'In izrezal je na njih kerube in palme in razvito cvetje in jih prevlekel z zlatom, prikladnim za izrezljaje.',
        36: 'In zgradil je notranje dvorišče: tri vrste obsekanih kamenov in vrsto cedrovih brun.',
        37: 'V četrtem letu je bil položen temelj hiši Gospodovi, v mesecu Zivu.',
        38: 'V enajstem letu pa, v mesecu Bulu, ki je osmi mesec, je bila hiša dokončana z vso opravo svojo in po vsej uredbi svoji. Tako jo je zidal sedem let.',
    },
    7: {
        1: 'Svojo hišo pa je Salomon zidal trinajst let, dokler je ni vse dokončal.',
        2: 'Zidal je namreč hišo libanonskega gozda; njena dolgost je bila sto komolcev in širjava petdeset komolcev in višava trideset komolcev, na štirih vrstah cedrovih stebrov, s cedrovimi bruni na stebrih.',
        3: 'In pokrita je bila po vrhu s cedrovino nad sobami, ki so slonele na stebrih, petinštirideset, po petnajst v eni vrsti.',
        4: 'In bilo je tri vrste brun, in okno proti oknu po treh vrstah.',
        5: 'In vsa vrata in podboji so bili štirivoglati, s tramovjem, in okno proti oknu po treh vrstah.',
        6: 'In naredil je stebrnato dvorano, ki je bila petdeset komolcev dolga in trideset komolcev široka, pred njo pa vežo iz stebrov in prag pred njo.',
        7: 'Tudi je naredil dvorano za prestol, kjer je sodil, sodno dvorano, in jo je obložil s cedrovino, od konca do kraja tal.',
        8: 'Tudi hiša njegova, ki je v njej prebival, na drugem dvorišču proti dvorani, je bila enako delana. Tudi je naredil hišo za hčer Faraonovo (ki si jo je bil vzel Salomon za ženo), enako tej dvorani.',
        9: 'To vse je bilo napravljeno iz dragih kamenov, po merilu obsekanih, z žago rezanih po znotranji in zunanji strani, od temelja do vrha sten in od zunaj do velikega dvorišča.',
        10: 'Podstave pa so bile iz dragih velikih kamenov, po deset in po osem komolcev velikih.',
        11: 'In vrhu njih so bili dragi kameni, obsekani po voglomeru, in cedrovina.',
        12: 'Veliko dvorišče pa je imelo naokoli tri vrste obsekanih kamenov in vrsto cedrovih brun, enako kakor notranje dvorišče hiše Gospodove in hišna veža.',
        13: 'Poslal pa je kralj Salomon ter dal poklicati Hirama iz Tira,',
        14: 'ki je bil sin žene vdove iz rodu Neftalijevega, in oče njegov je bil mož iz Tira, umeten bronar. Ta je bil poln modrosti, razuma in umetelnosti, izgotavljati vsakovrstna dela iz kovine. In prišel je h kralju Salomonu in izvršil vse delo njegovo.',
        15: 'Ulil je namreč tista dva stebra iz brona; vsak je bil osemnajst komolcev visok, in vrvica, dvanajst komolcev dolga, ju je vsakega ovijala.',
        16: 'In napravil je dva glaviča iz litega brona, da se posadita gori na stebra, in vsak glavič je bil pet komolcev visok.',
        17: 'Mrežasta pletenina in spletene verižice so bile ob glavičih vrhu stebrov, sedmero na enem in sedmero na drugem glaviču.',
        18: 'In naredil je margaranova jabolka po dve vrsti okoli stebrov na eni pletenini, da bi prestirala glaviča, ki sta bila vrhu stebrov, in enako je napravil tudi pri drugem glaviču.',
        19: 'In glaviča, ki sta bila vrhu stebrov, sta bila lilijastega dela kakor v veži, štiri komolce.',
        20: 'In glaviča sta bila tudi zgoraj na obeh stebrih blizu trupa, ki je bil poleg pletenine; in bilo je margaranovih jabolk dvesto v vrstah okoli na drugem glaviču.',
        21: 'In postavil je ta stebra pri veži ob templju in desnega je imenoval Jakina in levega Boaza.',
        22: 'In na vrhu stebrov je bilo lilijasto delo. In tako sta bila stebra dodelana.',
        23: 'Naredil je tudi ulito morje, deset komolcev od roba do roba, okroglo okoli, pet komolcev visoko; in vrvica tridesetih komolcev ga je kroginkrog ovijala.',
        24: 'Pod njegovim robom kroginkrog je šel nakit bučkastega sadja, po deset buček na komolec; v dveh vrstah so bile bučke, ulite sceloma z morjem.',
        25: 'Stalo je na dvanajstih volih, ki so trije gledali proti severu in trije proti zahodu, trije proti jugu in trije proti vzhodu; in morje je bilo položeno na njih, vsi njih zadki pa so bili pod morjem.',
        26: 'ln debelost njegova je bila eno dlan, in njegov rob je bil zaokrožen kakor rob keliha, kakor lilijevo cvetje; in držalo je dva tisoč batov.',
        27: 'Naredil je tudi deset stojal iz brona: vsako stojalo štiri komolce dolgo in štiri komolce široko in tri komolce visoko.',
        28: 'In stojala so bila tako narejena, da so imela ploščine med obrobnimi letvicami;',
        29: 'in na ploščinah med obrobnimi letvicami izrezljane leve, vole in kerube; in na letvicah zgoraj je bil podstavek; zdolaj pa pod levi in voli so bili viseči venci.',
        30: 'In vsako stojalo je imelo štiri bronasta kolesa in bronaste osi; in na štirih voglih njegovih so bila držala, za pod umivalnik so bila držala prilita, ob vsakem so bili venci.',
        31: 'In odprtina je bila na njem vrh pokrova, komolec visoka in okrogla, v obliki stojala, en komolec in pol poprek; in tudi ob odprtini so bili izrezljaji. Njegove ploščine pa so bile štirivoglate, ne okrogle.',
        32: 'In tista štiri kolesa so bila pod letvicami; in osi koles so bile utrjene na stojalu; vsako kolo je bilo en komolec in pol visoko.',
        33: 'In kolesa so bila narejena kakor vozna kolesa; njih osi in platišča in napere in pesta, vse je bilo ulito.',
        34: 'Bila so tudi štiri držala na štirih spodnjih voglih vsakega stojala, ki so izhajala iz stojala samega.',
        35: 'In vrhu stojal je bil pol komolca zvišek, okroglast kroginkrog; in na zgornjem kraju stojala so bila njegova držala in njegove ploščine enakega dela ž njim.',
        36: 'In vdolbel je na deske njegovih držal in na njegove ploščine kerube, leve in palme, kolikor je bilo prostora na vsaki, in vence kroginkrog.',
        37: 'Na ta način je naredil tistih deset stojal: vsa so bila enega zlitka, ene mere in ene oblike.',
        38: 'In naredil je deset bronastih umivalnikov, štirideset batov je držal eden in vsak je bil štiri komolce širok, in na vsakem tistih desetih stojal je bil po en umivalnik.',
        39: 'Postavil pa je pet stojal na desno in pet na levo stran hiše; a morje je postavil na desno stran hiše ob vzhodu, proti jugu.',
        40: 'In Hiram je naredil lonce in lopate in čaše. Tako je dokončal Hiram vse delo, ki ga je delal za kralja Salomona v hiši Gospodovi:',
        41: 'dva stebra in dva vrčasta glaviča, ki sta bila vrhu stebrov; in dve mrežasti pletenini, ki sta bili v prestrtje obema vrčastima glavičema na vrhu stebrov;',
        42: 'in štiristo margaranovih jabolk k dvema pleteninama: po dve vrsti margaranov za vsako pletenino, v prestrtje obema vrčastima glavičema na vrhu stebrov;',
        43: 'in desetero stojal in deset umivalnikov na stojalih;',
        44: 'morje eno in dvanajst volov pod morjem;',
        45: 'in lonce in lopate in čaše. In vse te priprave, ki jih je delal Hiram za kralja Salomona v hiši Gospodovi, so bile iz zlikane bronovine.',
        46: 'V Jordanski dolini jih je dal kralj zliti, v ilovnati zemlji med Sukotom in Zaretanom.',
        47: 'In Salomon je pustil vse te posode nepretehtane, zaradi prevelike množine niso mogli dognati teže bronovini.',
        48: 'In naredil je Salomon vse tiste posode, ki so bile v hiši Gospodovi: zlati oltar in zlato mizo, na kateri so bili kruhi obličja,',
        49: 'in svečnike, pet po desni in pet po levi strani pred govoriščem, iz prečiščenega zlata, in cvetlice, svetilnice in utrinjače iz zlata;',
        50: 'in vrče, usekalnike, čaše, torila, kadilnice iz prečiščenega zlata, tudi tečaje za duri notranje hiše, Najsvetejšega, in za duri templjeve dvorane, iz zlata.',
        51: 'In tako je bilo vse delo dokončano, ki ga je delal kralj Salomon v hiši Gospodovi. In Salomon je znesel tja reči, ki jih je posvetil David, oče njegov, srebro in zlato in posode, in zložil jih je v zakladih hiše Gospodove.',
    },
    8: {
        1: 'Tedaj je zbral kralj Salomon k sebi v Jeruzalem starejšine Izraelove in vse poglavarje rodov, kneze očetovinam sinov Izraelovih, da prineso skrinjo zaveze Gospodove gori iz mesta Davidovega, to je Sion.',
        2: 'In vsi možje so se zbrali h kralju Salomonu v mesecu Etanimu, to je sedmi mesec, ob prazniku.',
        3: 'In pridejo vsi starejšine Izraelovi, in duhovniki vzdignejo skrinjo,',
        4: 'in neso gori skrinjo Gospodovo in shodni šator in vse svete posode, ki so bile v šatoru; duhovniki in leviti so jih prinesli gori.',
        5: 'In kralj Salomon in vsa občina Izraelova, kar se jih je zbralo pri njem, so ž njim bili pred skrinjo in so darovali drobnice in govedi toliko, da se ni računila, ne štela zaradi množine.',
        6: 'In duhovniki prineso skrinjo zaveze Gospodove na njeno mesto, v govorišče hiše, v Najsvetejše, pod peruti kerubov;',
        7: 'zakaj keruba sta razprostirala peruti nad mestom skrinje, in keruba sta pokrivala skrinjo in njena droga odzgoraj.',
        8: 'Droga pa sta bila toliko dolga, da sta se njuna konca videla iz svetišča pred govoriščem, ali zunaj ju ni bilo videti; in ondi sta do današnjega dne.',
        9: 'Ničesar ni bilo v skrinji razen dveh kamenenih desek, ki ju je vanjo vložil Mojzes na Horebu, kjer je Gospod sklenil zavezo s sinovi Izraelovimi, ko so bili šli iz Egipta.',
        10: 'In ko so šli duhovniki iz svetišča, je oblak napolnil hišo Gospodovo,',
        11: 'da niso mogli duhovniki stati, da opravljajo službo, spričo oblaka; kajti slava Gospodova je napolnila hišo Gospodovo.',
        12: 'Tedaj reče Salomon: Jehova je rekel, da bo prebival v mrakoti.',
        13: 'Zidal in dozidal sem ti hišo v prebivališče, stan tebi za sedež na vekomaj.',
        14: 'In kralj obrne obličje in blagoslovi ves zbor Izraelov; in ves zbor Izraelov je stal.',
        15: 'In reče: Hvaljen bodi Gospod, Bog Izraelov, ki je obljubil z usti svojimi očetu mojemu Davidu in z roko svojo to izpolnil, rekoč:',
        16: 'Od dne, ko sem odpeljal ljudstvo svoje Izraela iz Egipta, nisem izvolil nobenega mesta iz vseh rodov Izraelovih, da zgradi hišo, ki bi v njej prebivalo moje ime; ali izvolil sem Davida, da bodi nad mojim ljudstvom Izraelom.',
        17: 'Bilo je res na srcu Davidu, očetu mojemu, da sezida hišo imenu Gospoda, Boga Izraelovega.',
        18: 'Toda Gospod je dejal očetu mojemu Davidu: Ker ti je bilo na srcu sezidati hišo mojemu imenu, si dobro storil, da si to imel v srcu.',
        19: 'Ali ti mi ne boš zidal hiše, marveč sin tvoj, ki pride iz ledja tvojega, ta bo zgradil hišo mojemu imenu.',
        20: 'In Gospod je vzdržal besedo svojo, ki jo je bil govoril, in jaz sem nastopil na očeta svojega Davida mesto in sem sedel na prestol Izraelov, kakor je bil govoril Gospod, in zgradil sem hišo imenu Jehove, Boga Izraelovega;',
        21: 'in tam sem pripravil mesto za skrinjo, ki je v njej zaveza Gospodova, katero je sklenil z očeti našimi, ko jih je peljal iz Egiptovske dežele.',
        22: 'Nato stopi Salomon pred oltar Gospodov vpričo vsega zbora Izraelovega in razprostre roke proti nebu',
        23: 'in reče: O Gospod, Bog Izraelov, tebi ni enakega Boga v nebesih gori in na zemlji doli, ki hraniš zavezo in milost hlapcem svojim, kateri hodijo pred obličjem tvojim z vsem srcem svojim;',
        24: 'ki si ohranil hlapcu svojemu Davidu, očetu mojemu, kar si mu bil obljubil; z usti svojimi si govoril in z roko svojo si to izpolnil, kakor se danes vidi.',
        25: 'In sedaj, Gospod, Bog Izraelov, ohrani hlapcu svojemu Davidu, očetu mojemu, kar si mu bil obljubil, govoreč: Ne bo ti zmanjkalo moža pred obličjem mojim, ki bo sedel na prestolu Izraelovem, samo če pazijo sinovi tvoji na svojo pot, da hodijo pred menoj, kakor si ti hodil pred menoj.',
        26: 'Sedaj torej, o Bog Izraelov, naj se, prosim, uresniči beseda tvoja, ki si jo govoril hlapcu svojemu Davidu, očetu mojemu.',
        27: 'Toda v resnici prebiva li Bog na zemlji? Glej, nebo in vseh nebes nebesa te ne morejo obseči, koliko manj ta hiša, ki sem jo sezidal!',
        28: 'Vendar se obrni k molitvi svojega hlapca in k njegovi prošnji, Gospod, moj Bog, da poslušaš glas in molitev, ki jo moli hlapec tvoj pred teboj danes:',
        29: 'da bodo oči tvoje odprte proti tej hiši po dne in po noči, proti mestu, ki si o njem rekel: Moje ime bode ondi, da uslišiš molitev, ki jo bo molil hlapec tvoj na tem mestu.',
        30: 'Poslušaj torej prošnjo hlapca svojega in ljudstva svojega Izraela, ki jo bodo prosili obrnjeni proti temu mestu, poslušaj na mestu prebivanja svojega, v nebesih, poslušaj in odpuščaj!',
        31: 'Ako se kdo pregreši zoper bližnjega svojega in se mu naloži prisega, da se zaveže s prisego, in prisega pride pred tvoj oltar v tej hiši:',
        32: 'ti poslušaj v nebesih in stóri, da se pravica zgodi hlapcem tvojim, s tem, da obsodiš krivičnega ter mu pripraviš pot njegovo nad glavo, pravičnega pa opravičiš ter mu poplačaš po pravičnosti njegovi.',
        33: 'Kadar bo sovražnik porazil pred seboj ljudstvo tvoje, Izraela, ker so grešili zoper tebe, pa se zopet obrnejo k tebi in pripoznajo tvoje ime in bodo molili in ponižno prosili tebe v tej hiši:',
        34: 'ti poslušaj v nebesih in odpusti greh ljudstva svojega Izraela ter jih zopet pripelji v deželo, ki si jo dal njih očetom.',
        35: 'Kadar se zapre nebo, da ni dežja, ker so grešili zoper tebe, pa bodo molili obrnjeni proti temu mestu in pripoznavali tvoje ime, in se obrnejo od grehov svojih, ker si jih ponižal:',
        36: 'ti poslušaj v nebesih ter odpusti greh hlapcev svojih in ljudstva svojega Izraela, da jih učiš dobro pot, po kateri naj hodijo, in pošlješ dežja na deželo svojo, ki si jo dal v dediščino ljudstvu svojemu.',
        37: 'Kadar bode v deželi lakota, kadar pride kuga ali snet ali rja, kobilice ali gosenice; ko jih bo sovražnik oblegal v deželi njih mest; katerakoli bode nadloga, katerakoli bolezen:',
        38: 'kakršnokoli molitev in prošnjo opravlja kdo izmed vsega tvojega ljudstva Izraela, kadar spoznajo vsakteri srca svojega kazen in razprostro roke proti tej hiši:',
        39: 'ti poslušaj v nebesih, v mestu prebivanja svojega, in odpusti ter stóri, da daš vsakemu, kakor je živel, ker poznaš njegovo srce (zakaj ti, edini ti poznaš vseh človeških otrok srca),',
        40: 'da bi se te bali vse svoje žive dni v deželi, ki si jo dal očetom našim.',
        41: 'Ako pa tudi inostranec, ki ni iz ljudstva tvojega Izraela, pride iz daljne dežele zaradi imena tvojega',
        42: '(slišali bodo namreč o tvojem velikem imenu in o mogočni roki tvoji in o iztegnjeni rami tvoji), ko torej pride in bo molil proti tej hiši:',
        43: 'ti poslušaj v nebesih, v mestu prebivanja svojega, in stori vse, za kar te kliče inostranec; da spoznajo vsi narodi na zemlji tvoje ime, da bi se te bali kakor ljudstvo tvoje Izrael ter da se prepričajo, da se imenuje ta hiša, ki sem jo zgradil, po imenu tvojem.',
        44: 'Kadar pojde ljudstvo tvoje na vojsko zoper sovražnika svojega, po kateremkoli potu jih pošlješ, in bodo molili h Gospodu, ozirajoč se proti mestu, ki si ga izvolil, in proti hiši, ki sem jo zgradil imenu tvojemu:',
        45: 'ti poslušaj v nebesih njih molitev in prošnjo ter se potegni za njih pravdo.',
        46: 'Kadar se pregreše zoper tebe (kajti ni človeka, ki ne greši) in se razsrdiš ter jih izročiš sovražniku, da jih ujete peljejo v sovražnikov deželo, daleč ali blizu;',
        47: 'pa se v svojem srcu premislijo v deželi, kamor so bili ujeti odpeljani, in se izpreobrnejo in te ponižno prosijo v deželi tistih, ki so jih ujete odvedli, govoreč: Grešili smo, krivično smo delali, brezbožno smo ravnali!',
        48: 'ako se k tebi povrnejo iz vsega srca svojega in iz vse duše svoje v deželi sovražnikov svojih, ki so jih ujete odpeljali, in bodo molili k tebi, ozirajoč se proti deželi svoji, ki si jo dal njih očetom, proti mestu, ki si ga izvolil, in proti hiši, ki sem jo zgradil imenu tvojemu:',
        49: 'ti poslušaj njih molitev in prošnjo v nebesih, v mestu prebivanja svojega, ter se potegni za njih pravdo',
        50: 'in odpusti ljudstvu svojemu, kar so grešili zoper tebe, in vse prestopke, s katerimi so prestopili zoper tebe, ter jim daj milost pred temi, ki jih imajo ujete, da se jih usmilijo:',
        51: 'kajti tvoje ljudstvo so in tvoja dediščina, ki si jo peljal iz Egipta, iz peči železne.',
        52: 'Tako naj bodo oči tvoje odprte proti prošnji hlapca tvojega in prošnji ljudstva tvojega Izraela, da jih slišiš, kadarkoli kličejo k tebi.',
        53: 'Zakaj ti si jih odločil sebi v dediščino izmed vseh ljudstev zemlje, kakor si govoril po Mojzesu, hlapcu svojem, ko si peljal očete naše iz Egipta, o Gospod Jehova!',
        54: 'In ko je Salomon izmolil in končal vso to molitev in prošnjo do Gospoda, vstane izpred oltarja Gospodovega, kjer je pripognil kolena in iztegnil roke proti nebu.',
        55: 'In pristopi in blagoslovi ves zbor Izraelov z glasom velikim, govoreč:',
        56: 'Hvaljen bodi Gospod, ki je dal pokoj svojemu ljudstvu Izraelu po vsem, kakor je govoril! Ni izginila ena beseda izmed njegovih dobrih obljub, ki jih je govoril po Mojzesu, hlapcu svojem.',
        57: 'Gospod, naš Bog, bodi z nami, kakor je bil z očeti našimi, ne zapusti nas in ne zavrzi nas,',
        58: 'da nagne srca naša k sebi, da bi hodili po vseh potih njegovih in izpolnjevali zapovedi njegove, postave in sodbe njegove, ki jih je zapovedal očetom našim.',
        59: 'Te moje besede pa, s katerimi sem prosil pred Gospodom, naj bodo blizu Gospoda, našega Boga, po dne in po noči, da se poteguje za pravdo hlapca svojega in za pravdo svojega ljudstva Izraela, kolikor je vsak dan treba:',
        60: 'da bi spoznala vsa ljudstva na zemlji, da Gospod je Bog, nobenega ni drugega.',
        61: 'Vaše srce pa bodi popolnoma vdano Gospodu, Bogu našemu, da živite po postavah njegovih in izpolnjujete zapovedi njegove, kakor je danes.',
        62: 'In kralj in ves Izrael ž njim je daroval daritve pred Gospodom.',
        63: 'In Salomon je zaklal mirovnih daritev, ki jih je poklonil Gospodu, dvaindvajset tisoč goved in stoindvajset tisoč glav drobnice. Tako so posvečevali kralj in vsi sinovi Izraelovi hišo Gospodovo.',
        64: 'Tisti dan je kralj posvetil sredino dvorišča, ki je pred hišo Gospodovo; zakaj tam je daroval žgalne in jedilne žrtve in tolstino mirovnih daritev, ker bronasti oltar, ki je bil pred Gospodom, je bil premajhen, da bi prejel žgalne in jedilne žrtve in tolstino mirovnih daritev.',
        65: 'In Salomon in ves Izrael ž njim, velik zbor, ki se je sešel od vhoda v Hamat tja do Egiptovskega potoka, je praznoval tisti čas praznik pred Gospodom, našim Bogom, sedem dni in zopet sedem dni, to je štirinajst dni.',
        66: 'Osmi dan je razpustil ljudstvo; in oni so, blagoslovivši kralja, odšli v šatore svoje veseli in dobre volje zaradi vseh dobrot, ki jih je storil Gospod svojemu hlapcu Davidu in svojemu ljudstvu Izraelu.',
    },
    9: {
        1: 'In ko je končal Salomon zidanje hiše Gospodove in kraljeve hiše in vse, kar je želel napraviti, kar ga je veselilo,',
        2: 'se mu prikaže Gospod v drugič, kakor se mu je bil prikazal v Gibeonu.',
        3: 'In Gospod mu reče: Uslišal sem molitev in prošnjo tvojo, ki si jo molil pred menoj. Posvetil sem to hišo, ki si jo zgradil, da tam postavim ime svoje za večno, in moje oči in srce moje bodo tam vekomaj.',
        4: 'Tebi pa, ako boš hodil pred menoj, kakor je hodil David, oče tvoj, s popolnoma vdanim srcem in v poštenosti, da boš delal vse, kakor sem ti zapovedal, izpolnjujoč moje postave in sodbe moje:',
        5: 'tebi utrdim kraljestva tvojega prestol nad Izraelom za večno, kakor sem obljubil očetu tvojemu Davidu, govoreč: Ne bo ti zmanjkalo moža na prestolu Izraelovem.',
        6: 'Ako se pa odvrnete, da ne bi šli za menoj, vi in otroci vaši, in ne boste izpolnjevali zapovedi mojih, postav mojih, ki sem vam jih predpisal, temuč pojdete in boste služili drugim bogovom ter jih molili:',
        7: 'tedaj potrebim Izraela s površja zemlje, ki sem jim jo dal, in to hišo, ki sem jo posvetil imenu svojemu, vržem izpred svojega obličja, in Izrael bode v pregovor in v zabavljico med vsemi ljudstvi.',
        8: 'In ob tej hiši, bodisi še tako visoka, se bo vsak mimogredoči zavzel in žvižgal; in poreko: Zakaj je Gospod tako storil tej deželi in tej hiši?',
        9: 'In odgovore: Zato ker so zapustili Gospoda, Boga svojega, ki je izpeljal njih očete iz dežele Egiptovske, in se oklenili drugih bogov ter jih molili in jim služili. Zato je Gospod nadnje pripravil vso to nesrečo!',
        10: 'In zgodi se ob koncu dvajsetih let, v katerih je Salomon zidal tisti dve hiši, hišo Gospodovo in kraljevo hišo,',
        11: 'ki je zanju Hiram, kralj tirski, oskrboval Salomona s cedrovino in cipresovino in z zlatom, kolikor je le želel: tedaj da kralj Salomon Hiramu dvajset mest v Galilejski deželi.',
        12: 'Nato se odpravi Hiram iz Tira, da ogleda mesta, ki mu jih je dal Salomon; a niso mu bila pogodu.',
        13: 'In reče: Kakšna so ta mesta, ki si mi jih dal, brat moj? In jih je imenoval deželo Kabul do današnjega dne.',
        14: 'Poslal pa je Hiram kralju stoindvajset talentov zlata.',
        15: 'In to je razlog roboti, ki jo je nabral kralj Salomon: da bi zidal hišo Gospodovo in hišo svojo in Milo in obzidje jeruzalemsko in Hazor in Megido in Gezer.',
        16: 'Faraon namreč, egiptovski kralj, je bil prišel gori in dobil Gezer ter ga požgal z ognjem in pomoril Kanaance, ki so prebivali v mestu, ter ga je dal v delež hčeri svoji, ženi Salomonovi.',
        17: 'Salomon je torej sezidal Gezer in Bethoron Dolenji',
        18: 'in Baalat in Tadmor v puščavi, v deželi,',
        19: 'in mesta za skladišča Salomonova in mesta za vozove in mesta za konjike njegove in kar je želel Salomon sezidati sebi v veselje v Jeruzalemu in na Libanonu in po vsej deželi gospostva svojega.',
        20: 'Kar jih je pa preostalo od Amorejcev, Hetejcev, Ferizejcev, Hevejcev in Jebusejcev, ki niso bili iz sinov Izraelovih,',
        21: 'iz njih otrok namreč, ki so po njih ostali v deželi in jih niso dočista mogli iztrebiti sinovi Izraelovi, iz teh je Salomon nabral robotnikov, do tega dne.',
        22: 'A izmed sinov Izraelovih ni storil nikogar za sužnja, ampak bili so vojaki in služabniki njemu in vojvode njegovi in poveljniki in načelniki nad njegovimi vozovi in konjiki.',
        23: 'Višjih oblastnikov, ki so nadzorovali delo Salomonovo, je bilo petsto in petdeset, ki so gospodovali ljudstvu, opravljajočemu delo.',
        24: 'Ko pa se je hči Faraonova preselila iz mesta Davidovega v hišo svojo, ki ji jo je zgradil, tedaj je sezidal Milo.',
        25: 'In trikrat na leto je daroval Salomon žgalne in mirovne žrtve na oltarju, ki ga je bil zgradil Gospodu, in je dal žgati kadilo na onem, ki je bil pred Gospodom. In tako je dokončal hišo.',
        26: 'In kralj Salomon je napravil ladje v Ezion-geberju, ki je pri Elotu, na bregu Rdečega morja, v Edomski deželi.',
        27: 'In Hiram je poslal po ladjah hlapce svoje, brodarje, ki so bili zvedeni na morju, s hlapci Salomonovimi.',
        28: 'In dospeli so v Ofir in tam naložili zlata štiristo in dvajset talentov ter ga pripeljali kralju Salomonu.',
    },
    10: {
        1: 'Ko pa je slišala kraljica v Sabi Salomonov sloves zaradi imena Gospodovega, ga je prišla izkušat z ugankami.',
        2: 'Pride torej v Jeruzalem z jako velikim spremstvom, z velblodi, ki so nesli dišave in zlata jako mnogo in drage kamene. In ko je dospela k Salomonu, je govorila ž njim o vsem, kar ji je bilo na srcu.',
        3: 'In Salomon ji je razložil vse, kar ga je vprašala; ni bilo besede, ki bi bila skrita kralju, da bi ji ne bil povedal.',
        4: 'Ko pa je čula kraljica iz Sabe vso modrost Salomonovo in videla hišo, ki jo je zgradil,',
        5: 'in jed na mizi njegovi in prebivališča hlapcev njegovih in strežbo služabnikov njegovih ter njih obleko in njegove točaje in njegove stopnice, po katerih je hodil gori v hišo Gospodovo, ji je od strmenja sapa zastala;',
        6: 'in reče kralju: Resnična je bila beseda, ki sem jo slišala v deželi svoji o tvojih stvareh in o tvoji modrosti!',
        7: 'Toda nisem hotela verjeti, dokler nisem prišla in sem s svojimi očmi videla vse. In glej, še polovice mi niso povedali: več imaš modrosti in dobrot, nego je bila govorica, ki sem jo slišala.',
        8: 'Blagor tvojim ljudem in blagor tem tvojim hlapcem, ki vedno stoje pred teboj, ki poslušajo modrost tvojo!',
        9: 'Hvaljen bodi Gospod, Bog tvoj, ki ti je bil blagovoljen, da te je posadil na prestol Izraelov! Ker Gospod ljubi Izraela vekomaj, zato te je postavil za kralja, da izvršuješ sodbo in pravičnost.',
        10: 'In dala je kralju stoindvajset talentov zlata in silno veliko dišav in dragih kamenov; nikdar več ni prišla tolika množina dišav kakor ta, ki jo je dala kraljica iz Sabe Salomonu.',
        11: 'Vrhutega so pripeljale Hiramove ladje, ki so nosile zlato iz Ofirja, silno veliko sandalovine in dragih kamenov iz Ofirja.',
        12: 'In kralj je dal napraviti iz sandalovine opirala za hišo Gospodovo in za kraljevo hišo, tudi harfe in citre pevcem. Take sandalovine ni prišlo več, tudi je ni bilo videti do današnjega dne.',
        13: 'In kralj Salomon je dal kraljici iz Sabe vse, kar je želela in kar je prosila, razen tega, kar ji je poklonil po kraljevi darežljivosti. In vrne se ter odide v deželo svojo, ona in njeni hlapci.',
        14: 'Teža zlata pa, ki se je prinašalo Salomonu na leto, je bila šeststo šestdeset in šest talentov,',
        15: 'razen tega, kar ga je prišlo s popotniki in s trgovci in od vseh kraljev arabskih in od namestnikov po deželi.',
        16: 'In kralj Salomon je dal napraviti dvesto ščitov iz tolkljanega zlata: šeststo seklov zlata je porabil za en ščit;',
        17: 'in tristo malih ščitov iz tolkljanega zlata, po tri mine zlata je šlo na en ščit. In kralj jih je zložil v hiši libanonskega gozda.',
        18: 'Dalje je na pravil kralj velik prestol iz slonovih kosti in ga je prevlekel z najboljšim zlatom.',
        19: 'Šestero stopnic je držalo do prestola, in vrh prestolov je bil okrogel odzadaj, in na obeh straneh pri sedežu sta bili naslonili, in dva leva sta stala ob naslonilih.',
        20: 'In dvanajst levov je stalo na tej in na oni strani ob šesterih stopnicah; kaj takega ni bilo videti v nobenem kraljestvu.',
        21: 'Pa tudi vse posode, iz katerih je pil kralj Salomon, so bile zlate, in vsa oprava v hiši libanonskega gozda je bila iz čistega zlata, nič ni bilo srebrno, kajti srebra niso sploh cenili v Salomonovih dnevih.',
        22: 'Kralj je imel tarsko brodovje na morju z brodovjem Hiramovim; po enkrat na tri leta so dospevale ladje tarske, noseč zlata in srebra, slonovih kosti, opic in pavov.',
        23: 'In kralj Salomon je nadkriljeval vse kralje zemlje v bogastvu in v modrosti.',
        24: 'In vsa zemlja je hrepenela po obličju Salomonovem, da bi slišali modrost njegovo, ki mu jo je dal Bog v srce.',
        25: 'In prinašali so vsakdo svoje darilo: posode srebrne in posode zlate, oblačila in orožje in dišave, konje in mezge, vsako leto, kar je bilo pristojno.',
        26: 'In Salomon je nabral voz in konjikov in je imel tisoč in štiristo voz in dvanajst tisoč konjikov, ki jih je razstavil po voznih mestih in pri kralju v Jeruzalemu.',
        27: 'In kralj je storil, da je bilo v Jeruzalemu toliko srebra kakor kamenov, in ceder je napravil toliko kakor smokovega drevja, ki raste v ravnini.',
        28: 'In konje je Salomon dobival iz Egipta; družba kraljevih kupcev jih je privajala trume za kupno ceno.',
        29: 'Voz pa je prišel gori, odpeljan iz Egipta, po šeststo seklov srebra, in konj po sto in petdeset. Tako so jih dobivali tudi vsi kralji Hetejcev in sirski kralji po njih roki.',
    },
    11: {
        1: 'A kralj Salomon je ljubil mnogo inostranskih žen poleg hčere Faraonove: Moabke, Amonke, Edomke, Sidonke in Hetejke;',
        2: 'iz narodov, o katerih je Gospod rekel sinovom Izraelovim: Ne hodite mednje, tudi oni naj ne hodijo med vas, kajti gotovo vam naklonijo srce, da pojdete za njih bogovi. Na te se je navezal Salomon v ljubezni.',
        3: 'In imel je sedemsto žen kneginj in tristo priležnic; in žene so odvrnile srce njegovo.',
        4: 'In ko je bil Salomon star, so mu njegove žene naklonile srce, da je šel za drugimi bogovi; in ni bilo srce njegovo popolnoma vdano Gospodu, Bogu njegovemu, kakor je bilo srce njegovega očeta Davida.',
        5: 'In Salomon je hodil za Astoreto, boginjo Sidoncev, in za Milkomom, gnusobo Amoncev.',
        6: 'In Salomon je počenjal, kar je bilo hudo v očeh Gospodovih, ter ni hodil popolnoma za Gospodom kakor njegov oče David.',
        7: 'Takrat je sezidal Salomon višavo Kamosu, gnusobi Moabcev, na gori, ki je pred Jeruzalemom, in Molohu, gnusobi sinov Amonovih.',
        8: 'In tako je storil za vse svoje žene tujke, ki so žgale kadilo in darovale svojim bogovom.',
        9: 'In Gospod se je razsrdil nad Salomonom, ker je odvrnil srce svoje od Gospoda, Boga Izraelovega, ki se mu je bil prikazal dvakrat',
        10: 'in mu je prav o tem zapovedal, naj ne hodi za drugimi bogovi; a on ni izpolnil, kar mu je bil Gospod zapovedal.',
        11: 'Zato je dejal Gospod Salomonu: Ker je bilo to pri tebi ter nisi ohranil zaveze moje in postav mojih, ki sem ti jih zapovedal, gotovo ti odtrgam kraljestvo in ga dam hlapcu tvojemu.',
        12: 'Ali v tvojih dneh ne storim tega zaradi Davida, očeta tvojega; sinu tvojemu ga odtrgam iz roke.',
        13: 'Vendar pa nočem vsega kraljestva odtrgati, ali en rod dam tvojemu sinu, zaradi Davida, služabnika svojega, in zaradi Jeruzalema, ki sem ga izvolil.',
        14: 'Obudil pa je Gospod nasprotnika Salomonu, Hadada Edomca; on je bil iz kraljevega rodu v Edomu:',
        15: 'Takrat namreč, ko je bil David v Edomu in je Joab, poveljnik vojske, šel gori pokopat pobite, in ko je bil pomoril vse moštvo v Edomu',
        16: '(kajti Joab in ves Izrael je ostal šest mesecev ondi, dokler ni pokončal vsakega moškega v Edomu),',
        17: 'je zbežal Hadad, on in nekateri Edomci iz hlapcev očeta njegovega ž njim, da pojdejo v Egipt. Hadad pa je bil še majhen deček.',
        18: 'In vstali so iz Madianske in prišli v Paran, in vzeli so s seboj može iz Parana in so prišli v Egipt k Faraonu, kralju egiptovskemu. Ta je dal Hadadu hišo in mu določil živež ter mu odkazal zemljo.',
        19: 'In Hadad je našel veliko milost v očeh Faraonovih, tako da mu je dal za ženo sestro žene svoje, kraljice Tahpenese sestro.',
        20: 'In sestra Tahpenesina mu je rodila sina Genubata, in Tahpenes ga je vzgajala v hiši Faraonovi; Genubat je torej bil v Faraonovi hiši med sinovi Faraonovimi.',
        21: 'In ko je slišal Hadad v Egiptu, da je David zaspal z očeti svojimi ter da je Joab, poveljnik vojske, mrtev, reče Faraonu: Odpusti me, da grem v svojo deželo.',
        22: 'Tedaj ga vpraša Faraon: Česa ti manjka pri meni, da hočeš iti v deželo svojo? Odgovori: Ničesar, pa me vsekakor pusti!',
        23: 'In Bog mu je obudil drugega nasprotnika, Rezona, sina Eljadovega, ki je bil pobegnil gospodarju svojemu Hadadezerju, kralju v Zobi.',
        24: 'In zbral je k sebi mož in je postal načelnik trume, ko je David udaril Zobljane; in šli so v Damask in v njem prebivali in je zakraljeval v Damasku.',
        25: 'In bil je nasprotnik Izraelu vse dni Salomonove; in to je bilo nad zlo, ki mu ga je napravljal Hadad; in gnusilo se mu je do Izraela, in zakraljeval je v Siriji.',
        26: 'Tudi Jeroboam, sin Nebatov, Efraimec iz Zerede, hlapec Salomonov, (čigar mati se je imenovala Zerua, in bila je vdova), je vzdignil roko zoper kralja.',
        27: 'In to je vzrok, zakaj je vzdignil roko zoper kralja: Salomon je zidal Milo in je zadelal razpoklino mesta Davida, očeta svojega.',
        28: 'Tisti mož pa, Jeroboam, je bil vrl junak, in ko je Salomon videl mladeniča, da je marljiv, ga je postavil nad vso tlako Jožefove hiše.',
        29: 'Zgodi se pa v tistem času, ko je Jeroboam šel iz Jeruzalema, da ga zaloti na potu prorok Ahija Silonski; ogrnil se je pa bil z novim oblačilom, in bila sta sama na polju.',
        30: 'In prime Ahija novo oblačilo, ki ga je imel na sebi, ter ga raztrga na dvanajst kosov',
        31: 'in veli Jeroboamu: Vzemi si deset kosov! kajti tako pravi Gospod, Bog Izraelov: Glej, hočem odtrgati kraljestvo iz roke Salomonove in tebi dati deset rodov:',
        32: '(en rod pa naj mu ostane zaradi hlapca mojega Davida in zaradi Jeruzalema, mesta, ki sem ga izvolil izmed vseh rodov Izraelovih)',
        33: 'zato, ker so me zapustili ter se priklanjali Astoreti, boginji Sidoncev, Kamosu, bogu Moabcev, in Milkomu, bogu sinov Amonovih, in niso hodili po mojih potih, da se ravnajo po tem, kar je prav v mojih očeh, in po mojih postavah in sodbah kakor David, oče njegov.',
        34: 'Nočem mu pa vzeti vsega kraljestva iz roke, ampak postavim ga za kneza vse dni življenja njegovega zaradi Davida, hlapca svojega, ki sem ga izvolil, ki se je ravnal po zapovedih in postavah mojih.',
        35: 'Vzamem pa kraljestvo iz roke sinu njegovega ter ga dam tebi, namreč desetero rodov.',
        36: 'A sinu njegovemu dam en rod, da bo imel David, hlapec moj, svetilo vselej pred obličjem mojim v Jeruzalemu, v mestu, ki sem si ga izvolil, da ondi postavim ime svoje.',
        37: 'Tebe torej vzamem, in gospodoval boš vsemu, kakor želi duša tvoja, in bodeš kralj nad Izraelom.',
        38: 'In ako boš poslušal vse, kar ti zapovedujem, in hodil po mojih potih in delal, kar je prav v mojih očeh, izpolnjujoč moje postave in zapovedi, kakor je delal hlapec moj David: hočem biti s teboj in ti postaviti hišo stanovitno, kakor sem jo postavil Davidu, in ti dati Izraela.',
        39: 'In zaradi tega bom poniževal seme Davidovo, a ne vse dni.',
        40: 'Salomon pa je gledal, kako bi usmrtil Jeroboama, ali Jeroboam vstane in zbeži v Egipt k Sisaku, kralju egiptovskemu, in bil je v Egiptu do smrti Salomonove.',
        41: 'O drugih pa rečeh Salomonovih in o vsem, kar je storil, in o modrosti njegovi, ni li zapisano v knjigi dejanj Salomonovih?',
        42: 'Časa pa, ki je v njem Salomon kraljeval v Jeruzalemu vsemu Izraelu, je bilo štirideset let.',
        43: 'In legel je Salomon k očetom svojim in bil je pokopan v mestu Davida, očeta svojega; in Roboam, sin njegov, je zakraljeval na mestu njegovem.',
    },
    12: {
        1: 'In Roboam je šel v Sihem, kajti ves Izrael je prišel v Sihem, da ga postavijo za kralja.',
        2: 'In slišal je o tem Jeroboam, sin Nebatov (bil pa je še v Egiptu, kamor je bil zbežal izpred kralja Salomona; prebival je torej Jeroboam v Egiptu,',
        3: 'in poslali so ter ga poklicali). In pride Jeroboam in ves zbor Izraelov in govoré k Roboamu, rekoč:',
        4: 'Oče tvoj nam je preobtežal jarem; sedaj torej nam polajšaj pretrdo službo očeta svojega in težki jarem, ki nam ga je naložil, in bomo ti služili.',
        5: 'In on jim reče: Odidite še do tretjega dne, potem se vrnite k meni. In ljudstvo odide.',
        6: 'In kralj Roboam se je posvetoval s starci, ki so stali v službi pri njegovem očetu Salomonu, ko je še živel, rekoč: Kako mi svetujete, da naj odgovorim temu ljudstvu?',
        7: 'In ga ogovore in reko: Ako se danes postrežljivega izkažeš temu ljudstvu in mu storiš po volji in če jih uslišiš in jim govoriš prijazne besede, ti bodo hlapci vse dni.',
        8: 'Ali on je zavrgel svet starcev, ki so mu ga dali, in se je posvetoval z mladeniči, ki so vzrasli ž njim in so stali v službi pred njim.',
        9: 'In jih vpraša: Kaj svetujete, da naj odgovorimo temu ljudstvu, ki so govorili k meni, rekoč: Polajšaj jarem, ki nam ga je naložil oče tvoj!',
        10: 'Tedaj mu reko mladiči, ki so ž njim vzrasli: Ljudstvu, ki ti je dejalo: Oče tvoj nam je preobtežal jarem, ti pa nam ga polajšaj! takole odgovóri: Moj mali prst je večji nego mojega očeta ledje.',
        11: 'Sedaj torej: oče moj vas je obremenil s težkim jarmom, a jaz še pridenem jarmu vašemu; oče moj vas je tepel z biči, jaz pa vas bom s trnovkami.',
        12: 'Tedaj pride Jeroboam in vse ljudstvo k Roboamu tretji dan, kakor je kralj velel, rekoč: Pridite k meni zopet tretji dan.',
        13: 'In kralj je odgovoril ljudstvu trdo in zapustil svet starcev, ki so mu ga bili dali,',
        14: 'ter jim je govoril po svetu mladičev takole: Oče moj vam je naložil težek jarem, jaz pa še pridenem jarmu vašemu; oče moj vas je tepel z biči, jaz pa vas bom s trnovkami.',
        15: 'Kralj torej ni ugodil ljudstvu, kajti Gospod je tako ravnal, da potrdi besedo svojo, ki jo je govoril Gospod po Ahiju Silonskem Jeroboamu, sinu Nebatovemu.',
        16: 'In ko je videl ves Izrael, da jim kralj ni ugodil, odgovori ljudstvo kralju in reče: Kakšen delež nam je v Davidu? in dediščine nimamo v sinu Jesejevem. K svojim šatorom, o Izrael! Sedaj glej hišo svojo, David! In Izrael se je razšel v šatore svoje.',
        17: 'Samo sinovom Izraelovim, ki so prebivali v Judovih mestih, je kraljeval Roboam.',
        18: 'Nato pošlje kralj Roboam Adorama, ki je bil nad roboto, a ves Izrael ga je lučal s kamenjem, da je umrl. In pohiti kralj Roboam in stopi na svoj voz, da pobegne v Jeruzalem.',
        19: 'Tako je odstopil Izrael od hiše Davidove do tega dne.',
        20: 'In ko zasliši ves Izrael, da se je vrnil Jeroboam iz Egipta, pošljejo ga poklicat v ljudski zbor, ter ga postavijo za kralja nad vsem Izraelom. Nihče ni šel za hišo Davidovo nego Judov rod edini.',
        21: 'Ko pa dospe Roboam v Jeruzalem, zbere vso hišo Judovo in rod Benjaminov, sto in osemdeset tisoč izbranih vojščakov, da se bojujejo s hišo Izraelovo in zopet pridobe kraljestvo Roboamu, sinu Salomonovemu.',
        22: 'Pa pride beseda Božja Semaju, možu Božjemu, govoreč:',
        23: 'Govóri Roboamu, sinu Salomonovemu, Judovemu kralju, in vsej hiši Judovi in Benjaminovi in drugemu ljudstvu, in véli:',
        24: 'Tako pravi Gospod: Ne hodite gori in ne bojujte se s svojimi brati, sinovi Izraelovimi; vrnite se vsak v hišo svojo, zakaj od mene je prišla ta reč. In slušali so besedo Gospodovo in se vrnili domov, kakor je velel Gospod.',
        25: 'Tedaj je Jeroboam sezidal Sihem na Efraimskem gorovju in prebival v njem; in odtod je šel dalje in sezidal Penuel.',
        26: 'Dejal je pa Jeroboam v srcu svojem: Kraljestvo bi se sedaj lahko povrnilo hiši Davidovi.',
        27: 'Ako hodi to ljudstvo gori darovat žrtve v hiši Gospodovi v Jeruzalemu, se obrne srce tega ljudstva h gospodarju svojemu, k Roboamu, kralju Judovemu, in me bodo umorili ter se povrnili k Roboamu, kralju Judovemu.',
        28: 'Zato se je kralj posvetoval, ter naredi dve zlati teleti in jim veli: Preveč je za vas hoditi gori v Jeruzalem! Glej, to so bogovi tvoji, Izrael, ki so te pripeljali gori iz dežele Egiptovske!',
        29: 'In postavi eno v Betel, eno pa v Dan.',
        30: 'In ta reč je postala v greh, zakaj ljudstvo je hodilo molit pred tisto eno tele tja do Dana.',
        31: 'In napravil je hiše višav in postavil za duhovnike vsake vrste ljudi, ki niso bili izmed sinov Levijevih.',
        32: 'In določil je praznik v osmem mesecu, petnajsti dan meseca, po podobi praznika, ki je bil na Judovem, in je daroval na oltarju. Tako je storil v Betelu ter je daroval teletoma, ki ju je bil naredil; in namestil je v Betelu duhovnike višav, ki jih je napravil.',
        33: 'In stopil je gori k oltarju, ki ga je zgradil v Betelu, petnajsti dan osmega meseca, tistega meseca, ki si ga je izmislil v srcu svojem; in je napravil praznik sinovom Izraelovim ter je pristopil k oltarju zažigat kadilo.',
    },
    13: {
        1: 'A glej, mož Božji pride z Judovega po besedi Gospodovi v Betel, in Jeroboam stoji pri oltarju, da zažge kadilo.',
        2: 'In zakliče zoper oltar po besedi Gospodovi in reče: Oltar, oltar, tako pravi Gospod: Glej, sin se bo rodil hiši Davidovi, po imenu Josija, in na tebi bo daroval duhovnike višav, ki žgo kadilo na tebi, in človeške kosti bodo palili na tebi.',
        3: 'In dal je tisti dan znamenje, rekoč: To je znamenje, da je govoril Gospod: Glej, oltar se razpoči in pepel, ki je na njem, se razsuje.',
        4: 'In ko zasliši kralj besedo moža Božjega, ki jo je vzkliknil zoper oltar v Betelu, iztegne Jeroboam roko svojo od oltarja pa veli: Primite ga! A roka njegova, ki jo je iztegnil zoper njega, je usehnila, da je ni mogel zopet potegniti k sebi.',
        5: 'Oltar se je tudi razpočil in pepel se je razsul z oltarja natančno po znamenju, ki ga je bil dal mož Božji po besedi Gospodovi.',
        6: 'In kralj izpregovori ter reče možu Božjemu: Poprosi, prosim, blagovoljnosti Gospoda, Boga svojega, in moli zame, da se mi zopet povrne roka moja. Nato zaprosi mož Božji blagovoljnosti Gospodove, in kralju se je roka povrnila in bila je zdrava kakor prej.',
        7: 'Tedaj ogovori kralj moža Božjega: Pojdi z mano domov in se pokrepčaj, in dam ti darilo.',
        8: 'A mož Božji reče kralju: Ko bi mi dal polovico hiše svoje, ne pojdem s teboj, ker nočem jesti kruha, ne piti vode na tem mestu.',
        9: 'Zakaj tako mi je zapovedano po besedi Gospodovi, ki mi je velela: Ne jej ondi kruha in ne pij vode, tudi se ne vračaj po potu, po katerem si šel.',
        10: 'In odšel je po drugem potu, da se ne vrne po tistem potu, po katerem je prišel v Betel.',
        11: 'Neki star prorok pa je prebival v Betelu; k temu pridejo sinovi njegovi ter mu pripovedujejo vse, kar je storil mož Božji tisti dan v Betelu; tudi besede, ki jih je govoril kralju, povedo očetu svojemu.',
        12: 'In vpraša jih njih oče: Po katerem potu je odšel? In pokažejo mu sinovi njegovi pot, po katerem je odšel mož Božji, ki je bil prišel z Judovega.',
        13: 'Nato veli sinovom svojim: Osedlajte mi osla! In ko so mu osedlali osla, je jezdeč na njem',
        14: 'šel za možem Božjim ter ga je zalotil sedečega pod hrastom in mu reče: Si li ti mož Božji, ki je prišel z Judovega? Odgovori: Sem.',
        15: 'Tedaj mu reče: Pojdi z mano domov in zaužij kruha!',
        16: 'On pa reče: Ne smem se vrniti in s teboj iti, tudi nočem s teboj jesti kruha, ne piti vode na tem mestu;',
        17: 'zakaj bilo mi je rečeno po besedi Gospodovi: Ne jej ondi kruha in ne pij vode! po poti, po kateri si prišel, se zopet ne vračaj!',
        18: 'Ta mu pa reče: Tudi jaz sem prorok kakor ti in angel mi je govoril po besedi Gospodovi, veleč: Pelji ga nazaj s seboj v hišo svojo, da užije kruha in pije vode. To pa se mu je zlagal.',
        19: 'Vrne se torej ž njim, da zaužije kruha in se napije vode v hiši njegovi.',
        20: 'Ko sta pa sedela pri mizi, pride beseda Gospodova proroku, ki ga je nazaj pripeljal,',
        21: 'in zavpije proti možu Božjemu, ki je prišel z Judovega, rekoč: Tako pravi Gospod: Ker si bil nepokoren ustom Gospodovim in nisi izpolnil zapovedi, ki ti jo je zapovedal Gospod, Bog tvoj,',
        22: 'temuč si se vrnil in jedel kruh in pil vodo na tem mestu, o katerem ti je velel: Ne jej ondi kruha in ne pij vode: zato ne pride truplo tvoje v očetov tvojih grob!',
        23: 'In potem, ko je zaužil kruha in se napil, mu je osedlal osla, proroku, katerega je bil vrnil.',
        24: 'In ko je šel, naleti nanj lev na poti ter ga usmrti; in truplo njegovo je ležalo na poti in osel je stal pri njem, lev pa je tudi stal poleg trupla.',
        25: 'In glej, ljudje so šli mimo in videli truplo na tleh na poti in leva stoječega pri truplu, in pridejo ter oznanijo v mestu, kjer je prebival stari prorok.',
        26: 'In ko to začuje prorok, ki ga je nazaj pripeljal s pota, reče: Mož Božji je, ki je bil nepokoren ustom Gospodovim; zato ga je Gospod izročil levu, ki ga je raztrgal in usmrtil po besedi Gospodovi, ki mu jo je bil govoril.',
        27: 'In govori s sinovi svojimi in veli: Osedlajte mi osla! In osedlajo.',
        28: 'In odide in najde truplo njegovo na poti ter osla in leva, stoječa pri truplu. Ni jedel lev trupla in ni strl osla.',
        29: 'Tedaj vzdigne prorok truplo moža Božjega ter ga dene na osla in prinese nazaj, in pridejo v mesto starega proroka, da žalujejo in ga pokopljejo.',
        30: 'In on položi truplo njegovo v svoj grob, in žalujejo nad njim, govoreč: Gorje, moj brat!',
        31: 'In ko ga je pokopal, govori sinovom svojim in reče: Kadar umrjem, pokopljite me v grobu, v katerem je pokopan mož Božji; poleg njegovih kosti položite kosti moje.',
        32: 'Zakaj gotovo se izpolni napoved, katero je po besedi Gospodovi klical zoper oltar v Betelu in zoper vse hiše višav, ki so po mestih Samarije.',
        33: 'Ali po tej zgodbi se Jeroboam ni odvrnil s hudobne poti svoje, ampak je postavil še več duhovnikov višavam izmed vsake vrste ljudi: kdorkoli mu je ugajal, njega je posvetil, da bodi duhovnik višavam.',
        34: 'In ta reč je postala v greh hiši Jeroboamovi, da je morala izginiti in biti potrebljena s površja zemlje.',
    },
    14: {
        1: 'V tem času je zbolel Abija, sin Jeroboamov.',
        2: 'In Jeroboam reče ženi svoji: Vstani, prosim, in preobleci se, da te ne spoznajo, da si žena Jeroboamova, ter pojdi v Silo; glej, tam je Ahija prorok, ki je govoril o meni, da bodem kralj temu ljudstvu.',
        3: 'In vzemi s seboj deset kruhov in kolačev in posodo medu ter pojdi k njemu; on ti naznani, kaj se zgodi z dečkom.',
        4: 'In žena Jeroboamova stori tako, in vstane ter odide v Silo in pride v hišo Ahijevo. Ahija pa ni mogel videti, kajti oči so mu bile premrle od starosti.',
        5: 'A Gospod je rekel Ahiju: Glej, žena Jeroboamova prihaja, vprašat te besedo zastran sina svojega; bolan je namreč. Zato ji govóri tako in tako! Kajti ko pride noter, se bo delala za tujo.',
        6: 'Ko torej zasliši Ahija šum njenih nog, brž ko je stopila med duri, ji veli: Pridi le, žena Jeroboamova! Čemu se delaš za tujko? kajti jaz ti sem poslan s trdim poročilom.',
        7: 'Pojdi, povej Jeroboamu: Tako pravi Gospod, Bog Izraelov: Ker sem te povišal izmed ljudstva in te postavil za vojvodo ljudstvu svojemu Izraelu',
        8: 'in sem odtrgal kraljestvo od hiše Davidove ter ga dal tebi, ti pa nisi bil kakor hlapec moj David, ki je izpolnjeval zapovedi moje in hodil za menoj z vsem srcem svojim, da bi delal samo to, kar je prav v mojih očeh,',
        9: 'temuč si delal hudo bolj nego vsi, ki so bili pred teboj; odšel si in si naredil drugih bogov in ulitih podob, da bi me dražil v jezo, mene pa si vrgel za hrbet svoj:',
        10: 'zato, glej, pripravim nesrečo nad Jeroboamovo hišo in iztrebim od Jeroboamovih vsakega moškega, i sužnjega i prostega v Izraelu, in dočista izmetem hišo Jeroboamovo, kakor se blato izmete, da ga ni več.',
        11: 'Njega, ki od Jeroboamovih umre v mestu, bodo žrli psi, kdor pa umre na polju, njega bodo žrle ptice nebeške, kajti Gospod je govoril to.',
        12: 'Vstani torej in pojdi domov, in kadar stopi noga tvoja v mesto, umrje deček.',
        13: 'In ves Izrael bo žaloval po njem, in ga pokopljejo, zakaj on edini od Jeroboamovih pride v grob, ker se je na njem našlo nekaj dobrega proti Gospodu, Bogu Izraelovemu, v hiši Jeroboamovi.',
        14: 'Gospod pa si obudi kralja nad Izraelom, ki zatre hišo Jeroboamovo tisti dan. In kako je že danes!',
        15: 'In Gospod udari Izraela, da se bo majal kakor trst v vodi, in izdere Izraela iz te dobre dežele, ki jo je dal njih očetom, ter jih razkropi onostran velereke, zato ker so si napravili svoje Ašere, da bi dražili Gospoda v jezo.',
        16: 'In izda Izraela sovražniku zaradi grehov Jeroboamovih, s katerimi je grešil in v greh zapeljeval Izraela.',
        17: 'Vstane torej žena Jeroboamova in odide in dospe v Tirzo, in ko stopi na prag hiše, umrje deček.',
        18: 'In so ga pokopali, in ves Izrael je žaloval za njim, kakor je bil govoril Gospod po hlapcu svojem, Ahiju proroku.',
        19: 'Druge zgodbe Jeroboamove pa, kako se je bojeval in kako je kraljeval, glej, pisano je v knjigi letopisov kraljev Izraelovih.',
        20: 'Dni pa, v katerih je kraljeval Jeroboam, je bilo dvaindvajset let. In legel je k očetom svojim, in Nadab, sin njegov, je zakraljeval na mestu njegovem.',
        21: 'Roboam pa, sin Salomonov, je kraljeval na Judovem. Roboam je bil enoinštirideset let star, ko je zakraljeval, in sedemnajst let je vladal v Jeruzalemu, v mestu, ki si ga je izvolil Gospod iz vseh rodov Izraelovih, da ondi postavi ime svoje. In matere njegove ime je bilo Naama Amonka.',
        22: 'In Juda je delal, kar je bilo hudo v očeh Gospodovih, in dražili so ga h gorečnosti z grehi svojimi, ki so jih počenjali mimo vsega, kar so storili njih očetje.',
        23: 'Kajti napravljali so si tudi višave in stebre s podobami in Ašere na vsakem visokem hribu in pod vsakim zelenim drevesom.',
        24: 'Pa tudi nečistosti posvečeni moški so bili v deželi, ti so počenjali vse gnusobe poganskih narodov, ki jih je bil Gospod pregnal pred sinovi Izraelovimi.',
        25: 'In zgodi se v petem letu kralja Roboama, da pride gori Sisak, kralj egiptovski, proti Jeruzalemu.',
        26: 'Ta je pobral zaklade hiše Gospodove in zaklade hiše kraljeve in vse, kar se je dalo vzeti, tudi vse ščite zlate je pobral, ki jih je bil napravil Salomon.',
        27: 'Namesto njih je naredil kralj Roboam ščite iz brona ter jih je izročil poveljnikom straže, ki so čuvali vrata hiše kraljeve.',
        28: 'In kadarkoli je kralj šel v hišo Gospodovo, so jih nosili stražarji, in potem so jih zopet prinesli v stražarnico.',
        29: 'Druge zgodbe Roboamove pa in vse, kar je storil, ni li pisano v knjigi letopisov kraljev Judovih?',
        30: 'Boj pa je bil med Roboamom in Jeroboamom vse njiju žive dni.',
        31: 'In Roboam je legel k očetom svojim, in pokopali so ga z očeti njegovimi v mestu Davidovem; ime matere njegove pa je bilo Naama Amonka. In Abijam, sin njegov, je zakraljeval na mestu njegovem.',
    },
    15: {
        1: 'V osemnajstem letu kralja Jeroboama, sina Nebatovega, je zakraljeval Abijam nad Judo.',
        2: 'Tri leta je kraljeval v Jeruzalemu; in materi njegovi je bilo ime Maaka, hči Abisalomova.',
        3: 'In živel je v vseh grehih očeta svojega, kar jih je on bil storil pred njim; in srce njegovo ni bilo popolnoma vdano Gospodu, Bogu svojemu, kakor je bilo srce Davida, očeta njegovega.',
        4: 'Ali zavoljo Davida mu je dal Gospod, Bog njegov, svetilo v Jeruzalemu, da je obudil njegovega sina za njim in ohranil obstanek Jeruzalemu,',
        5: 'zato ker je David delal, kar je bilo prav v očeh Gospodovih, in se ni umaknil ničemur, kar mu je velel, vse svoje žive dni, razen v zadevi Urija Hetejca.',
        6: 'Bil pa je boj med Roboamom in Jeroboamom, dokler je živel.',
        7: 'Druge zgodbe Abijamove in vse, kar je storil, ni li pisano v knjigi letopisov kraljev Judovih? In bila je vojska med Abijamom in Jeroboamom.',
        8: 'In Abijam je legel k očetom svojim, in pokopali so ga v mestu Davidovem. Asa pa, sin njegov, je zakraljeval na mestu njegovem.',
        9: 'V dvajsetem letu Jeroboama, kralja Izraelovega, je zakraljeval Asa nad Judo,',
        10: 'in je vladal enoinštirideset let v Jeruzalemu. In materi njegovi je bilo ime Maaka, hči Abisalomova.',
        11: 'In Asa je delal, kar je bilo prav v očeh Gospodovih, kakor David, oče njegov.',
        12: 'Kajti odpravil je nečistosti posvečene moške iz dežele in odstranil vse ostudne malike, ki so jih napravili njegovi očetje.',
        13: 'Vrhutega je odstavil Maako, mater svojo, da ne bi imela kraljičje oblasti, ker je bila naredila ostudno podobo Ašeri. In Asa je zatrl njeno ostudno podobo ter jo je sežgal pri potoku Kidronu.',
        14: 'Toda višav niso odpravili; vendar pa je bilo srce Asovo nerazdeljeno proti Gospodu vse njegove žive dni.',
        15: 'In prinesel je v hišo Gospodovo, kar je bil posvetil oče njegov in kar je sam posvetil, srebro, zlato in posode.',
        16: 'Bil pa je boj med Asom in Baasom, kraljem Izraelovim, vse njiju žive dni.',
        17: 'In Baasa, kralj Izraelov, je prišel gori proti Judi in je zidal Ramo, da bi nihče ne mogel hoditi sem ali tja na stran Asovo, kralja Judovega.',
        18: 'Tedaj je Asa pobral vse srebro in zlato, kar ga je preostalo v zakladnici hiše Gospodove in v zakladnici kraljeve hiše, in ga je izročil hlapcem svojim, ter jih je poslal k Ben-hadadu, sinu Tabrimona, sina Heziona, kralja v Siriji, ki je prebival v Damasku, da naj sporoče:',
        19: 'Zaveza je med menoj in teboj, med mojim in tvojim očetom; glej, pošljem ti v dar srebra in zlata: pojdi, razderi zavezo svojo z Baasom, kraljem Izraelovim, da se umakne od mene!',
        20: 'In Ben-hadad je ugodil kralju in je poslal vojsk svojih poveljnike zoper mesta Izraelova, in udarili so Ijon in Dan in Abel Betmaako in ves Kinerot z vso pokrajino Neftalijevo vred.',
        21: 'In ko je to slišal Baasa, je nehal zidati Ramo, in ostal je v Tirzi.',
        22: 'Nato je razglasil kralj Asa ukaz po vsem Judovem, da nikomur ni bilo izgovora. In pobrali so z Rame kamenje in les, s katerim je bil zidal Baasa, in kralj Asa je s tem zgradil Gebo Benjaminovo in Micpo.',
        23: 'Druge zgodbe Asove pa in vsa moč njegova in vse, kar je storil, in mesta, ki jih je sezidal, ali ni zapisano v knjigi letopisov kraljev Judovih? A v svoji starosti je bil bolan na nogah.',
        24: 'In legel je Asa k očetom svojim, in pokopali so ga ž njega očeti v mestu Davida, očeta njegovega. In Josafat, sin njegov, je zakraljeval na mestu njegovem.',
        25: 'Nadab pa, sin Jeroboamov, je zakraljeval Izraelu v drugem letu Asa, kralja Judovega, in kraljeval je nad Izraelom dve leti',
        26: 'in delal, kar je bilo zlo v očeh Gospodovih, in hodil po poti očeta svojega in v grehu njegovem, s katerim je bil v greh zavajal Izraela.',
        27: 'Baasa pa, sin Ahijev, iz Isaharjevega rodu, je storil zavezo zoper njega; in Baasa je ubil Nadaba pri Gibetonu, ki je Filistejcev mesto; kajti Nadab in ves Izrael je oblegal Gibeton.',
        28: 'V tretjem letu Asa, kralja Judovega, ga je usmrtil Baasa in je zakraljeval na mestu njegovem.',
        29: 'Komaj pa je bil nastopil kraljestvo, je pomoril vso hišo Jeroboamovo, in ni pustil od Jeroboamovih žive ne ene duše, dokler ga ni zatrl po besedi Gospodovi, ki jo je govoril po hlapcu svojem, Ahiju Silonskem,',
        30: 'zaradi grehov Jeroboamovih, ki jih je zagrešil in ž njimi zapeljeval v greh Izraela, zaradi draženja, s katerim je dražil v srd Gospoda, Boga Izraelovega.',
        31: 'Druge pa zgodbe Nadabove in vse, kar je storil, ni li pisano v knjigi letopisov kraljev Izraelovih?',
        32: 'In bil je boj med Asom in Baasom, kraljem Izraelovim, vse njiju žive dni.',
        33: 'V tretjem letu Asa, kralja Judovega, je zakraljeval Baasa, sin Ahijev, vsemu Izraelu v Tirzi in je vladal štiriindvajset let.',
        34: 'In delal je, kar je bilo hudo v očeh Gospodovih, in je hodil po poti Jeroboamovi in v grehu njegovem, ki je bil ž njim v greh zavajal Izraela.',
    },
    16: {
        1: 'In pride beseda Gospodova k Jehuju, sinu Hananovemu, zoper Baasa in reče:',
        2: 'Ker sem te povišal iz prahu in te postavil za vojvodo ljudstvu svojemu, Izraelu, ti pa si hodil po poti Jeroboamovi in v greh zapeljeval ljudstvo moje, Izraela, da so me v jezo dražili z grehi svojimi:',
        3: 'glej, dočista hočem pomesti po Baasu in po hiši njegovi in storim s tvojo hišo, kakor sem storil s hišo Jeroboama, sina Nebatovega.',
        4: 'Njega, ki umre od Baasovih v mestu, bodo žrli psi, in kdor njegovih umre na polju, ga bodo žrle ptice nebeške.',
        5: 'Druge zgodbe Baasove in kar je storil in moč njegova, ni li pisano v knjigi letopisov kraljev Izraelovih?',
        6: 'In Baasa je legel k očetom svojim, in pokopali so ga v Tirzi, in Ela, sin njegov, je zakraljeval na mestu njegovem.',
        7: 'Po proroku Jehuju, sinu Hananovem, je tudi prišla beseda Gospodova zoper Baasa in zoper vso hišo njegovo zaradi vsega zla, ki ga je storil pred obličjem Gospodovim, da bi ga dražil v jezo z delom rok svojih, ravnajoč kakor hiša Jeroboamova, tudi zato, da jo je pokončal.',
        8: 'V šestindvajsetem letu Asa, kralja Judovega, je zakraljeval Ela, sin Baasov, nad Izraelom v Tirzi in je vladal dve leti.',
        9: 'In njegov služabnik Zimri, poveljnik polovice voz njegovih, je storil zavezo zoper njega. On pa je bil v Tirzi in je pil, da se je upijanil v hiši Arza, ki je bil oskrbnik dvorca v Tirzi.',
        10: 'In Zimri je prišel noter in ga je udaril in usmrtil v sedemindvajsetem letu Asa, kralja Judovega, in je zakraljeval na mestu njegovem.',
        11: 'In ko je zakraljeval, komaj je bil zasedel prestol njegov, je pobil vso hišo Baasovo; ni pustil živega ne enega moškega, ne iz sorodnikov, ne iz prijateljev njegovih.',
        12: 'Tako je Zimri zatrl vso hišo Baasovo po besedi Gospodovi, ki jo je govoril po proroku Jehuju proti Baasu,',
        13: 'zaradi vseh grehov Baasovih in zaradi grehov sinu njegovega Ela, ki sta jih storila in ž njimi zapeljevala v greh Izraela, da bi dražili v srd Gospoda, Boga Izraelovega, z ničevostmi svojimi.',
        14: 'Druge zgodbe Elove pa in vse, kar je storil, ni li pisano v knjigi letopisov kraljev Izraelovih?',
        15: 'V sedemindvajsetem letu Asa, kralja Judovega, je kraljeval Zimri sedem dni v Tirzi. Ljudstvo pa je bilo utaborjeno proti Gibetonu, ki je bilo mesto Filistejcev.',
        16: 'Ko pa je ljudstvo, ki je bilo v taboru, slišalo poročilo: Zimri je storil zaroto in je tudi ubil kralja, je postavil ves Izrael tisti dan v taboru Omrija, poveljnika vojske, za kralja nad Izraelom.',
        17: 'In Omri je šel gori in ves Izrael ž njim od Gibetona, in so oblegali Tirzo.',
        18: 'In ko je videl Zimri, da je mesto dobljeno, je šel v trdnjavo kraljevega dvorca in zažgal kraljev dvorec nad seboj z ognjem in je poginil',
        19: 'za grehe svoje, ki jih je zagrešil, ker je delal, kar je bilo hudo v očeh Gospodovih, in ker je hodil po poti Jeroboamovi in v grehu njegovem, ki ga je bil začel, da zapelje v greh Izraela.',
        20: 'Druge pa zgodbe Zimrijeve in zarota, ki jo je napravil, ni li pisano v knjigi letopisov kraljev Izraelovih?',
        21: 'Takrat se je razdelilo ljudstvo Izraelovo v dve stranki: polovica ljudstva je šla za Tibnijem, sinom Ginatovim, da ga postavijo za kralja, in polovica je šla za Omrijem.',
        22: 'Ali ljudstvo, ki je šlo za Omrijem, je bilo močnejše nego ljudstvo, ki se je držalo Tibnija, sina Ginatovega. In Tibni je poginil, in zakraljeval je Omri.',
        23: 'V enemintridesetem letu Asa, kralja na Judovem, je zakraljeval Omri Izraelu; dvanajst let je vladal, šest let v Tirzi.',
        24: 'In kupil je goro Samarijo od Semerja za dva talenta srebra, in pozidal je goro in imenoval ime mesta, ki ga je sezidal, po imenu Semerja, gospodarja gore: Samarijo.',
        25: 'In Omri je delal, kar je bilo zlo v očeh Gospodovih, še huje je delal nego vsi, ki so bili pred njim.',
        26: 'Kajti hodil je po vseh potih Jeroboama, sina Nebatovega, in v grehih njegovih, s katerimi je v greh vodil Izraela, da dražijo v jezo Gospoda, Boga Izraelovega, z ničevostmi svojimi.',
        27: 'Druga pa dejanja Omrijeva, ki jih je storil, in hrabrost njegova, ki jo je izkazal, ni li pisano v knjigi letopisov kraljev Izraelovih?',
        28: 'In Omri je legel k očetom svojim, in pokopali so ga v Samariji, in Ahab, sin njegov, je zakraljeval na mestu njegovem.',
        29: 'V osemintridesetem letu Asa, kralja na Judovem, je zakraljeval Ahab, sin Omrijev, nad Izraelom, in vladal je Izraelu v Samariji dvaindvajset let.',
        30: 'In Ahab, sin Omrijev, je delal, kar je bilo hudo v očeh Gospodovih, bolj nego vsi, kar jih je bilo pred njim.',
        31: 'Zakaj kakor da bi mu bilo premalo, da je hodil v grehih Jeroboama, sinu Nebatovega, si je vzel za ženo še Jezabelo, hčer Etbaala, kralja Sidoncev, in je šel in služil Baalu ter ga je molil.',
        32: 'In zgradil je Baalu oltar v hiši Baalovi, ki jo je bil sezidal v Samariji.',
        33: 'Ahab je tudi naredil Ašero; sploh je Ahab več storil, da razdraži v jezo Gospoda, Boga Izraelovega, nego vsi kralji v Izraelu, ki so bili pred njim.',
        34: 'V dneh njegovih je zidal Hiel Betelski Jeriho: ko pa mu je položil podstavo, je izgubil Abirama, prvenca svojega, in ko mu je postavil vrata, je izgubil najmlajšega sina Seguba, po besedi Gospodovi, ki jo je govoril po Jozuetu, sinu Nunovem.',
    },
    17: {
        1: 'In Elija, Tisbljan, iz prebivalcev Gileadskih, je govoril Ahabu: Kakor res živi Jehova, Bog Izraelov, ki stojim pred njega obličjem, ne bode ta leta ne rose, ne dežja, razen le po besedi moji!',
        2: 'In beseda Gospodova pride k njemu, veleč:',
        3: 'Pojdi odtod in obrni se proti vzhodu ter se skrij pri potoku Keritu, ki teče proti Jordanu.',
        4: 'In iz potoka boš pil, krokarjem pa sem zapovedal, da te ondi žive.',
        5: 'Šel je torej in storil po besedi Gospodovi; šel je in bival pri potoku Keritu, ki teče proti Jordanu.',
        6: 'Krokarji pa so mu prinašali kruha in mesa zjutraj ter kruha in mesa zvečer, in iz potoka je pil.',
        7: 'In zgodi se za nekoliko časa, da je potok usahnil, zakaj dežja ni bilo v deželi.',
        8: 'In pride mu beseda Gospodova, veleč:',
        9: 'Vstani, pojdi v Sarepto pri Sidonu, in tam prebivaj; glej, zapovedal sem ondi ovdoveli ženi, da te oskrbuje.',
        10: 'Vstane torej in odide v Sarepto, in ko pride do mestnih vrat, glej, vdova je bila ondi in je pobirala dračje. In jo pokliče ter veli: Prinesi mi, prosim, malo vode v posodi, da pijem.',
        11: 'Ko ona gre, da prinese, pokliče za njo in veli: Prosim, prinesi mi tudi grižljaj kruha v roki svoji!',
        12: 'Ona odvrne: Kakor res živi Gospod, Bog tvoj, nimam ničesar pečenega, samo prgišče moke v skrinji in malo olja v vrču, in glej, ravnokar sem nabrala malo dračja, da stopim noter in to pripravim sebi in sinu svojemu, da jeva in umrjeva.',
        13: 'A Elija ji veli: Ne boj se! Pojdi in naredi, kakor si dejala, toda pripravi meni majhen kolač najprej ter mi ga prinesi in potem pripravi sebi in sinu svojemu.',
        14: 'Zakaj tako pravi Gospod, Bog Izraelov: Moka v skrinji ne bo pošla in olja v vrču ne bo zmanjkalo do dneva, ob katerem pošlje Gospod dež nad zemljo.',
        15: 'In je šla in naredila po besedi Elijevi. In je jedla, tudi on in ona in njena družina dosti dni.',
        16: 'Moka v skrinji ni pošla in olja v vrču ni zmanjkalo po besedi Gospodovi, ki jo je bil govoril po Eliju.',
        17: 'Zgodi se pa po teh rečeh, da zboli sin tiste žene, hišne gospodinje, in bolezen mu je bila tako huda, da ni bilo več sape v njem.',
        18: 'In reče Eliju: Kaj je meni s teboj, mož Božji? Prišel si k meni, da spraviš v spomin krivico mojo in da umoriš sina mojega!',
        19: 'On pa veli: Daj mi sem sina svojega! In ga vzame iz njenega naročja ter ga odnese v zgornjo izbo, kjer je prebival, in ga položi na posteljo svojo.',
        20: 'In kliče h Gospodu in reče: O Gospod, Bog moj, si li celo tej vdovi, pri kateri gostujem, hudo storil, ko si umoril sina njenega?',
        21: 'In se razprostre trikrat nad detetom in kliče h Gospodu, rekoč: Gospod, Bog moj, prosim, naj se vrne tega dečka duša zopet vanj!',
        22: 'In Gospod je uslišal glas Elijev, in duša dečkova se je povrnila vanj, in je oživel.',
        23: 'In Elija vzame dečka ter ga prinese iz zgornje izbe doli v hišo in ga izroči materi njegovi; in Elija reče: Glej, sin tvoj živi!',
        24: 'In žena reče Eliju: Sedaj sem spoznala, da si ti mož Božji in da beseda Gospodova v ustih tvojih je resnica.',
    },
    18: {
        1: 'In po mnogih dneh pride beseda Gospodova k Eliju, v tretjem letu, in veli: Pojdi, pokaži se Ahabu, da dam dežja na zemljo.',
        2: 'Šel je torej Elija, da se pokaže Ahabu. Bila je pa velika lakota v Samariji.',
        3: 'In Ahab pokliče Obadija, ki je bil oskrbnik dvorca (Obadija se je pa silno bal Gospoda;',
        4: 'in zgodilo se je, ko je Jezabela morila proroke Gospodove, da je Obadija vzel sto prorokov in jih je skril v jami, tu petdeset in tam petdeset, ter jih je oskrboval s kruhom in z vodo).',
        5: 'In Ahab veli Obadiju: Pojdi po deželi do vseh studencev in do vseh potokov, če morda kje najdemo trave in ohranimo konje in mezge, da ne izgubimo vse živine.',
        6: 'Razdelita si torej deželo, da jo prehodita; Ahab gre po eni poti sam in po drugem potu Obadija sam.',
        7: 'In ko je Obadija na poti, glej, pride mu Elija naproti; in ga spozna ter pade na obraz in reče: Si li ti, gospod moj Elija?',
        8: 'On odgovori: Jaz sem. Pojdi, povej svojemu gospodu: Glej, Elija je tu.',
        9: 'On pa reče: Kaj sem pregrešil, da hočeš dati mene, hlapca svojega, Ahabu v roko, da me umori?',
        10: 'Kakor resnično živi Gospod, Bog tvoj, ni ga naroda ali kraljestva, kamor ni poslal moj gospod te iskat; in ko so rekli: Ni ga tukaj, je zahteval prisego od tistega kraljestva in naroda, da te niso našli.',
        11: 'In sedaj mi veliš: Pojdi, povej gospodu svojemu: Glej, Elija je tu!',
        12: 'Lahko se zgodi, ko odidem od tebe, da te duh Gospodov odnese ne vem kam; in ko pridem in povem Ahabu zate, on pa te ne najde, tedaj me umori. In hlapec tvoj se boji Gospoda od mladosti svoje.',
        13: 'Niso li tebi, gospodu mojemu, povedali, kaj sem storil, ko je Jezabela morila proroke Gospodove? Da sem jih skril sto izmed prorokov Gospodovih v jami, tu petdeset, tam petdeset, in sem jih oskrboval s kruhom in z vodo?',
        14: 'In sedaj mi veliš: Pojdi, povej gospodu svojemu: Glej, Elija je tu! In me umori.',
        15: 'In Elija reče: Kakor res živi Gospod nad vojskami, ki stojim pred njega obličjem, gotovo se mu pokažem danes!',
        16: 'Tedaj gre Obadija naproti Ahabu in mu to naznani. Ahab pa krene Eliju naproti.',
        17: 'In ko Ahab ugleda Elija, mu reče: Si li tu ti, ki spravljaš v nesrečo Izraela?',
        18: 'On odgovori: Nisem jaz spravil v nesrečo Izraela, temuč ti in tvojega očeta hiša s tem, da ste zapustili zapovedi Gospodove in si ti hodil za Baali.',
        19: 'Sedaj torej pošlji in zberi k meni vsega Izraela pri gori Karmelu in prorokov Baalovih štiristo in petdeset, tudi štiristo prorokov Ašerinih, ki jedo z mize Jezabeline.',
        20: 'Ahab torej pošlje do vseh sinov Izraelovih in zbere proroke pri gori Karmelu.',
        21: 'In Elija stopi pred vse ljudstvo in reče: Kako dolgo omahujete na dve strani? Je li Gospod Bog, hodite za njim, če pa je Baal, hodite za njim! In ljudstvo mu ne odgovori besede.',
        22: 'Tedaj reče Elija ljudstvu: Jaz, jaz sam sem ostal prorok Gospodov, a prorokov Baalovih je štiristo in petdeset mož.',
        23: 'Dajte nam torej dva junca, in oni naj si izbero junca zase in ga razsekajo in polože na drva, ognja pa naj ne zanetijo; in jaz pripravim drugega junca ter ga položim na drva, ognja pa ne zanetim.',
        24: 'In kličite ime svojega boga, jaz pa bom klical ime Gospodovo: in Bog, ki odgovori z ognjem, ta bodi Bog. In vse ljudstvo odgovori in reče: Prav si govoril.',
        25: 'Nato reče Elija prorokom Baalovim: Izberite si enega junca in ga pripravite najprej, zakaj vas je veliko; in kličite ime svojega boga, ognja pa ne zanetite!',
        26: 'In vzamejo junca, ki jim je bil dan, in ga pripravijo, pa kličejo ime Baalovo od jutra do poldne, govoreč: O Baal, usliši nas! A ni bilo glasu, ne odgovora. In skačejo okoli oltarja, ki so ga naredili.',
        27: 'In ko je bilo že poldne, jih zasmehuje Elija in veli: Vpijte prav glasno, saj je vendar bog! nemara da je zatopljen v misli, ali je šel na stran, ali je na potovanju; morda spi in se prebudi!',
        28: 'In vpijejo glasno in se po svoji šegi bodejo z nožmi in sulicami, da je kri po njih tekla.',
        29: 'In ko je minil poldan, še prorokujejo, dokler ne pride čas, da se prinese večerna daritev, a ni bilo glasu, ne odgovora, ne nikogar, ki bi poslušal.',
        30: 'Tedaj veli Elija vsemu ljudstvu: Pristopite k meni! In ko pristopi ljudstvo k njemu, popravi oltar Gospodov, ki je bil razdrt.',
        31: 'In Elija vzame dvanajst kamenov, po številu rodov sinov Jakoba, ki se mu je zgodila beseda Gospodova, rekoč: Izrael bodi ime tvoje.',
        32: 'In iz teh kamenov zgradi oltar v imenu Gospodovem; in okoli oltarja naredi jarek, širok in globok za dvojno žitno merico.',
        33: 'In pripravi drva ter razseka junca in ga položi na drva. Pa veli: Napolnite štiri vrče z vodo in jo izlijte na žgalno žrtev in na drva.',
        34: 'In veli: Še v drugič storite to! In ko storé v drugič, veli: Storite še v tretjič! In store v tretje.',
        35: 'In voda je tekla okoli oltarja; pa tudi jarek je napolnil z vodo.',
        36: 'In ko pride čas, da se daruje večerna daritev, pristopi prorok Elija in reče: Gospod, Bog Abrahamov, Izakov in Izraelov, daj danes spoznati, da si ti Bog v Izraelu in da sem jaz hlapec tvoj in da sem storil vse to po besedi tvoji!',
        37: 'Odgovóri mi, o Gospod, odgovori mi! da spozna to ljudstvo, da si ti, o Gospod, Bog in si ti sam preobrnil njih srce.',
        38: 'Tedaj švigne doli ogenj Gospodov in požre žgalno daritev in drva in kamene in prst in poliže vodo, ki je bila v jarku.',
        39: 'In ko vse ljudstvo vidi to, popadajo na obraze in govore: Gospod je Bog! Gospod je Bog!',
        40: 'Elija pa jim veli: Primite proroke Baalove, da njih nobeden ne ubeži! In so jih prijeli. In Elija jih popelje doli k potoku Kisonu in jih ondi pomori.',
        41: 'In Elija veli Ahabu: Pojdi gori, jej in pij, kajti šumi, kakor da se bliža silen dež.',
        42: 'Ahab torej gre gori jest in pit. A Elija stopi na vrh Karmela in, pripognjen proti zemlji, skloni obraz svoj med kolena svoja.',
        43: 'In reče hlapcu svojemu: Pojdi gori in poglej proti morju! In gre gori in pogleda, pa reče: Ničesar ni. In mu veli: Pojdi spet tja, sedemkrat!',
        44: 'In ob sedmem potu reče: Glej, oblaček vstaja iz morja, majhen kakor moška roka. Pa veli: Pojdi in reci Ahabu: Zaprezi in pelji se doli, da te dež ne zadrži!',
        45: 'In medtem malo po malo zatemni nebo z oblaki in vetrom, in nastane velik dež. In Ahab sede na voz in se pelje v Jezreel.',
        46: 'Roka Gospodova pa je bila nad Elijem, in opasal si je ledje in tekel pred Ahabom do vhoda v Jezreel.',
    },
    19: {
        1: 'In Ahab je povedal Jezabeli vse, kar je storil Elija, tudi, kako je umoril vse proroke z mečem.',
        2: 'In pošlje Jezabela sla k Eliju, da sporoči: Bogovi naj mi store to in to naj še pridenejo, ako ne storim jutri ob tem času z življenjem tvojim, kakor si storil z življenjem onih.',
        3: 'In ko je zvedel to, vstane in odide zaradi življenja svojega in pride v Bersebo na Judovem in pusti ondi hlapca svojega.',
        4: 'Sam pa gre dalje v puščavo, en dan hoda, in pride in sede pod brinov grm in prosi zase, da bi umrl, govoreč: Zadosti mi je! sedaj, o Gospod, vzemi dušo mojo; kajti nisem boljši nego očetje moji!',
        5: 'In leže in zaspi pod brinovim grmom. A glej, angel se ga dotakne in mu veli: Vstani in jej!',
        6: 'In se ozre, in glej, pri glavi njegovi je bil kruh, pečen na gorkih kamenih, pa vrč vode. In ko zaužije in se napije, leže zopet.',
        7: 'In angel Gospodov pride zopet, v drugič, se ga dotakne in veli: Vstani in jej! kajti predolga je pot zate.',
        8: 'In vstane in je in pije in potuje v moči tiste jedi štirideset dni in štirideset noči, dokler ne pride do gore Božje, Horeba.',
        9: 'In ondi pride v votlino in tu prenoči. In glej, beseda Gospodova pride k njemu in mu reče: Kaj tu delaš, Elija?',
        10: 'Odgovori: Silno sem gorel za Gospoda, Boga nad vojskami; zakaj sinovi Izraelovi so zapustili zavezo tvojo, oltarje tvoje so razdrli in proroke tvoje pomorili z mečem, in ostal sem jaz sam, pa še meni strežejo po življenju!',
        11: 'In veli mu: Pojdi ven in stopi na goro pred Gospoda! In glej, Gospod je šel mimo, in veter, velik in močan, je podiral gore in razbijal skale pred Gospodom; a Gospoda ni bilo v vetru. Za vetrom pa pride potres, a Gospoda ni v potresu.',
        12: 'In za potresom ogenj, a Gospoda ni v ognju. In za ognjem tih in mil glas.',
        13: 'Ko pa to sliši Elija, si zagrne s plaščem obraz ter gre ven in se ustopi ob vhodu v votlino. In glej, glas mu izpregovori: Kaj delaš tu, Elija?',
        14: 'On reče: Silno sem gorel za Gospoda, Boga nad vojskami; zakaj sinovi Izraelovi so zapustili zavezo tvojo, oltarje tvoje so razdrli in proroke tvoje pomorili z mečem, in ostal sem jaz sam, pa še meni strežejo po življenju.',
        15: 'In Gospod mu veli: Pojdi, vrni se svojim potom po puščavi, v Damask; in ko prideš tja, pomazili Hazaela za kralja Siriji.',
        16: 'Jehuja pa, sina Nimsijevega, pomazili za kralja nad Izraelom, in Elizeja, sina Safatovega, iz Abel-mehole, pomazili za proroka namesto sebe.',
        17: 'In zgodi se, da kdor ubeži meču Hazaelovemu, ga umori Jehu, in kdor ubeži meču Jehujevemu, ga umori Elizej.',
        18: 'Storil sem pa, da mi jih ostane sedem tisoč v Izraelu, vsa kolena, ki se niso pripogibala gred Baalom, in vsaka usta, ki ga niso poljubljala.',
        19: 'In odide odondod ter zaloti Elizeja, sina Safatovega, da orje z dvanajstimi jarmi volov pred seboj, sam pa je bil pri dvanajstem. In Elija stopi k njemu in vrže svoj plašč na njega.',
        20: 'In on popusti voli in teče za Elijem in reče: Dovoli mi, prosim, da poljubim očeta svojega in mater svojo, in potem pojdem za teboj! Ta mu veli: Idi, vrni se! Kajti kaj sem ti storil?',
        21: 'In se obrne in odide od njega in vzame jarem volov ter ju zakolje; in skuha meso pri opravi, ki je bila na volih, in da ljudstvu, in so jedli. Potem vstane in hodi za Elijem in mu streže.',
    },
    20: {
        1: 'Ben-hadad pa, kralj sirski, je zbral vso vojsko svojo, in bilo je pri njem dvaintrideset kraljev pa konj in vozov; in pride in oblega Samarijo in se bojuje zoper njo.',
        2: 'In pošlje sporočnikov v mesto k Ahabu, kralju Izraelovemu, da mu reko: Tako pravi Ben-hadad:',
        3: 'Tvoje srebro in zlato je moje, in najboljše žene tvoje in otroci tvoji so tudi moji.',
        4: 'Kralj Izraelov pa odgovori in reče: Po besedi tvoji, gospod moj, kralj: tvoj sem in vse, kar imam.',
        5: 'A sporočniki pridejo zopet in reko: Tako govori Ben-hadad: Ker sem poslal k tebi, rekoč: Meni daš srebro in zlato svoje in žene in otroke svoje,',
        6: 'zato pošljem jutri ob tem času hlapce svoje k tebi, in preiščejo hišo tvojo in služabnikov tvojih hiše, in karkoli z veseljem gledaš, vzamejo v roke in odneso.',
        7: 'Tedaj skliče kralj Izraelov vse starejšine dežele in reče: Premislite, prosim, in glejte, da ima ta mož le hudo v mislih! Zakaj poslal je k meni po žene in otroke moje in po srebro in zlato moje, in mu nisem odklonil.',
        8: 'In vsi starejšine in vse ljudstvo mu reče: Ne poslušaj ga in ne vdaj se mu!',
        9: 'Zatorej veli sporočnikom Ben-hadadovim: Povejte gospodu mojemu, kralju: Vse, kar si sporočil hlapcu svojemu najprej, sem hotel storiti, a tega ne morem. In sporočniki odidejo in mu prineso ta odgovor.',
        10: 'Tedaj pošlje Ben-hadad in mu sporoči: To naj mi bogovi store in to še pridenejo, ako bode dosti prahu v Samariji, da ga vzame vsak iz ljudstva mojega, ki ga vodim, le peščico!',
        11: 'Kralj Izraelov odgovori in reče: Povejte mu: Kdor se opasuje z mečem, naj se še ne hvali kakor oni, ki ga deva od sebe.',
        12: 'In zgodi se, ko Ben-hadad sliši to sporočilo, ko je ravno pil s kralji v šatorih, da veli hlapcem svojim: Postavite se! In postavijo se v boj proti mestu.',
        13: 'In glej, prorok pristopi k Ahabu, kralju Izraelovemu, in reče: Tako pravi Gospod: Si videl vso to preveliko množico? Glej, jaz ti jo danes dam v roke, da spoznaš, da sem jaz Gospod.',
        14: 'In Ahab vpraša: Po kom? On odgovori: Tako pravi Gospod: Po mladeničih pokrajinskih poglavarjev. Nato vpraša: Kdo naj začne boj? Odgovori: Ti.',
        15: 'Tedaj prešteje mladeniče pokrajinskih poglavarjev, in bilo jih je dvesto in dvaintrideset; in za njimi prešteje vse ljudstvo, vse sinove Izraelove, sedem tisoč.',
        16: 'In gredo ven opoldne. Ben-hadad pa je pil in se opijanil v šatorih z dvaintridesetimi kralji, ki so mu bili prišli v pomoč.',
        17: 'A mladeniči pokrajinskih poglavarjev so šli ven prvi. In Ben-hadad pošlje pogledat, in oznanijo mu, rekoč: Možje gredo sem iz Samarije!',
        18: 'On veli: Bodisi, da prihajajo po mir, ali da se gredo vojskovat, primite jih žive!',
        19: 'Oni torej gredo iz mesta, mladeniči pokrajinskih poglavarjev, druga vojska pa za njimi,',
        20: 'in vsak udari moža sebi nasproti; in Sirci zbeže, in Izrael dere za njimi. Ben-hadad pa, kralj sirski, je zbežal na konju z jezdeci.',
        21: 'In kralj Izraelov pride iz mesta in potolče konje in vozove in porazi Sirce z velikim pobojem.',
        22: 'Potem pristopi prorok h kralju Izraelovemu in mu reče: Pojdi, ojači se in premisli in glej, kaj delaš; zakaj kralj Sirije pride gori zoper tebe, ko mine leto.',
        23: 'In služabniki sirskega kralja mu reko: Njih bogovi so bogovi gorá, zato so nas premagali. Da bi se mogli ž njimi bojevati na ravnem, gotovo jih zmagamo!',
        24: 'Zatorej stóri to: Odstrani kralje, vsakega z njegovega mesta, in postavi namestnike na njih mesta!',
        25: 'In oskrbi si vojsko, kakor je bila vojska, ki si jo izgubil, tudi konje in vozove, enake prejšnjim; in bojevali se bomo zoper nje na ravnem, in gotovo jih premagamo! In slušal je njih glas in je storil tako.',
        26: 'In ko je minilo leto, prešteje Ben-hadad Sirce in gre gori proti Afeku, da se bojuje zoper Izraela.',
        27: 'In sinovi Izraelovi se tudi preštejejo in oskrbe z živežem ter gredo proti njim; in sinovi Izraelovi se utabore nasproti njim kakor dve majhni čredi koz. Sircev pa je bilo polno v deželi.',
        28: 'In mož Božji pristopi in reče kralju Izraelovemu: Tako pravi Gospod: Ker so dejali Sirci: Gospod je Bog gorá, a ni Bog dolin, zato dam vso to veliko množico v tvojo roko, in spoznate, da sem jaz Gospod.',
        29: 'In taborili so eni nasproti drugim sedem dni. Sedmi dan pa se vname bitka, in sinovi Izraelovi pobijejo izmed Sircev stotisoč pešcev v enem dnevi.',
        30: 'Preostali pa so bežali v Afek, v mesto, in zidovje je padlo na preostalih sedemindvajset tisoč mož. Ben-hadad je tudi zbežal in pritekel v mesto, iz hrama v hram bežeč.',
        31: 'In hlapci njegovi mu reko: Poglej, slišali smo, da so kralji Izraelove hiše milostivi kralji; dovoli, prosimo, da si denemo raševnike okoli ledij in vrvi ob tilnike, pa pojdemo ven h kralju Izraelovemu; lahko da te ohrani v življenju.',
        32: 'Opašejo si torej raševnike in denejo vrvi ob tilnike in pridejo h kralju Izraelovemu, pa reko: Hlapec tvoj Ben-hadad pravi: Prosim te, daj mi živeti! On pa reče: Živi li še? Brat je moj!',
        33: 'To pa so smatrali možje za dobro znamenje in so hitro povzeli to besedo od njega in dejali: Brat tvoj je Ben-hadad. Nato on veli: Pojdite, pripeljite ga! Tedaj pride Ben-hadad ven k njemu, in on mu veli stopiti na svoj voz.',
        34: 'In Ben-hadad reče: Mesta, ki jih je vzel moj oče tvojemu očetu, ti povrnem, in napravi si ulice v Damasku, kakor je oče moj napravil v Samariji. Jaz pa, reče Ahab, te izpustim s to zavezo. Storil je torej ž njim zavezo in ga je odpustil.',
        35: 'In neki mož izmed proroških sinov reče tovarišu svojemu po besedi Gospodovi: Udari me, prosim! A mož ga ni hotel udariti.',
        36: 'Tedaj mu reče: Ker nisi slušal glasu Gospodovega, glej, umori te lev, brž ko pojdeš od mene. In komaj je šel od njega, naleti nanj lev in ga umori.',
        37: 'Nato se nameri na drugega moža ter mu reče: Udari me, prosim! In mož ga krepko udari in rani.',
        38: 'Prorok pa odide in se postavi kralju na poti in se pretvori z oglavno povezo nad očmi.',
        39: 'In ko gre kralj mimo, kliče kralju in reče: Hlapec tvoj je šel med boj, in glej, nekdo stopi vstran in mi pripelje moža in veli: Varuj tega moža! Ako ga bodo pogrešili, bode življenje tvoje namesto življenja njegovega, ali pa boš moral plačati talent srebra.',
        40: 'Ko pa je hlapec tvoj imel tu in tam opravilo, je mož izginil. In kralj Izraelov mu reče: Taka je sodba tvoja; sam si jo izrekel.',
        41: 'Tedaj sname hitro povezo z oči; in kralj Izraelov ga spozna, da je izmed prorokov.',
        42: 'On pa mu reče: Tako pravi Gospod: Ker si pustil iz roke svoje moža, ki sem ga jaz izročil pogubi, zato bo življenje tvoje za njega življenje in ljudstvo tvoje za njegovo ljudstvo!',
        43: 'In kralj Izraelov je šel hude volje in srdit v hišo svojo in je dospel v Samarijo.',
    },
    21: {
        1: 'In zgodi se po teh rečeh, da je imel Nabot Jezreelčan vinograd, ki je bil v Jezreelu poleg palače Ahaba, kralja v Samariji.',
        2: 'In Ahab ogovori Nabota in reče: Daj mi svoj vinograd, da si napravim iz njega zelnik, ker je blizu, tik hiše moje, in dam ti zanj boljši vinograd, ali, če ti je prav, dam ti srebra zanj, kolikor je vreden.',
        3: 'Nabot pa reče Ahabu: Gospod mi ne daj, da bi dal očetov svojih dediščino tebi!',
        4: 'In Ahab pride domov hude volje in srdit zaradi besede, ki mu jo je govoril Nabot Jezreelčan; kajti dejal mu je: Nikar ti ne dam očetov svojih dediščine! In leže na posteljo, obrne obraz in noče užiti kruha.',
        5: 'Tedaj pride noter k njemu Jezabela, žena njegova, in ga ogovori: Zakaj je duh tvoj tako užaljen, da še kruha ne ješ?',
        6: 'In ji reče: Ker sem govoril z Nabotom Jezreelčanom in mu rekel: Daj mi vinograd svoj za denar, ali pa ti dam, če ti je pogodu, drug vinograd zanj; on pa mi je odgovoril: Ne dam ti vinograda svojega!',
        7: 'In Jezabela, žena njegova, mu reče: Ne vladaš li ti sedaj kraljestva Izraelovega? Vstani in jej kruh in bodi dobre volje! Jaz ti hočem dati vinograd Nabota Jezreelčana.',
        8: 'Nato napiše liste v imenu Ahabovem in jih zapečati ž njegovim pečatom, in pošlje liste starejšinam in plemenitnikom, ki so prebivali z Nabotom v mestu njegovem.',
        9: 'In pisala je v listih takole: Razglasite post in posadite Nabota med prvake ljudstva;',
        10: 'in postavite dva moža, otroka Belijalova, proti njemu, da pričujeta zoper njega: Proklel si Boga in kralja. Nato ga peljite ven in ga lučajte s kamenjem, da umrje.',
        11: 'In njegovi someščani, starejšine in plemenitniki, ki so prebivali v mestu njegovem, store, kakor jim je Jezabela ukazala, prav kakor je bilo ukazano v listih, ki jih jim je poslala.',
        12: 'Razglasijo post in posade Nabota med prvake ljudstva.',
        13: 'In prideta tista dva moža, otroka Belijalova, in stopita predenj, in tista moža Belijalova izpričata zoper Nabota vpričo ljudstva, govoreč: Nabot je proklel Boga in kralja. Tedaj ga odvedejo iz mesta in ga lučajo s kamenjem, da je umrl.',
        14: 'Nato pošljejo k Jezabeli in sporoče: Nabot je s kamenjem posut in mrtev.',
        15: 'In kakor hitro zasliši Jezabela, da je Nabot s kamenjem posut in mrtev, veli Jezabela Ahabu: Vstani, posedi vinograd Nabota Jezreelčana, ki ti ga ni hotel dati za denar, kajti Nabot ne živi več, mrtev je.',
        16: 'In ko Ahab sliši, da je Nabot mrtev, vstane precej, da bi šel doli v vinograd Nabota Jezreelčana in ga vzel v posest.',
        17: 'A beseda Gospodova pride Eliju Tisbljanu, veleč:',
        18: 'Vstani, pojdi doli naproti Ahabu, kralju Izraelovemu, ki prebiva v Samariji; glej, on je v vinogradu Nabotovem, kamor je šel, da ga vzame v posest.',
        19: 'In govóri mu, rekoč: Tako pravi Gospod: Nisi li ubil in po sili vzel? In govóri ž njim in reci: Tako pravi Gospod: Na mestu, kjer so psi lizali Nabotovo kri, bodo lizali tudi tvojo, prav tvojo.',
        20: 'In Ahab reče Eliju: Si me li našel, sovražnik moj? On odgovori: Našel sem te, zato ker si se prodal, da delaš, kar je hudo v očeh Gospodovih.',
        21: 'Glej, jaz pripravim nesrečo nadte in dočista te izmetem, in iztrebim od Ahabovih vsakega moškega, sužnja in prostega v Izraelu,',
        22: 'in storim s hišo tvojo kakor s hišo Jeroboama, sina Nebatovega, in kakor s hišo Baasa, sina Ahijevega, zaradi draženja, s katerim si me dražil, in da si Izraela zapeljeval v greh.',
        23: 'Tudi o Jezabeli je govoril Gospod in rekel: Psi bodo žrli Jezabelo ob obzidju jezreelskem.',
        24: 'Kdor umre od Ahabovih v mestu, ga bodo žrli psi, in njega, ki umre na polju, bodo žrle ptice nebeške.',
        25: '(Saj ni bilo nikogar mimo Ahaba, ki se je prodal, da bi delal, kar je zlo v očeh Gospodovih, ker ga je izpodbadala Jezabela, žena njegova.',
        26: 'In velike gnusobe je počenjal s tem, da je hodil za grdimi maliki, prav po vsem, kar so delali Amorejci, ki jih je Gospod zapodil pred sinovi Izraelovimi.)',
        27: 'In ko je Ahab slišal te besede, si raztrga oblačila in dene raševnik na telo in se posti in spi v raševniku ter hodi pohlevno.',
        28: 'Tedaj pride beseda Gospodova Eliju Tisbljanu in reče:',
        29: 'Vidiš li, kako se je Ahab ponižal pred menoj? Ker se ponižuje pred menoj, ne pripravim nesreče v dneh njegovih; v dneh sinu njegovega pošljem nesrečo nad hišo njegovo.',
    },
    22: {
        1: 'In tri leta so bivali v miru, da ni bilo vojske med Sirijo in Izraelom.',
        2: 'In zgodi se v tretjem letu, da pride Josafat, kralj Judov, doli h kralju Izraelovemu.',
        3: 'In reče kralj Izraelov služabnikom svojim: Ne veste li, da je Ramot v Gileadu naš? In mi mirujemo in ga ne vzamemo iz roke sirskega kralja?',
        4: 'In reče Josafatu: Pojdeš li z menoj v boj proti Ramotu v Gileadu? Josafat odgovori kralju Izraelovemu: Bodem naj kakor ti, ljudstvo moje kakor ljudstvo tvoje, konji moji kakor konji tvoji!',
        5: 'Še reče Josafat kralju Izraelovemu: Vprašaj, prosim, danes besedo Gospodovo!',
        6: 'Tedaj skliče kralj Izraelov proroke, okoli štiristo mož, pa jih vpraša: Naj li grem v boj proti Ramotu v Gileadu ali naj to opustim? Odgovore: Pojdi gori, in Gospod ga da v roko kraljevo!',
        7: 'Josafat pa reče: Ni li sicer nobenega Gospodovega proroka tu, da bi ga povprašali?',
        8: 'In kralj Izraelov reče Josafatu: Še en mož je, po katerem moremo vprašati Gospoda, Mihaj, sin Imlov; ali jaz ga sovražim, zakaj ne prorokuje mi dobrega, nego zgolj hudo. Josafat reče: Ne govóri tako, kralj!',
        9: 'Tedaj pokliče kralj Izraelov enega dvornika in veli: Hitro pripelji sem Mihaja, sina Imlovega!',
        10: 'Kralj Izraelov in Josafat, kralj Judov, pa sta sedela vsak na svojem prestolu, po kraljevsko oblečena, na trgu pri vhodu v vrata Samarije, in vsi proroki so prorokovali pred njima.',
        11: 'In Zedekija, sin Kenaanov, si je naredil železne rogove in govoril: Tako pravi Gospod: S temi boš bodel Sirce, dokler jih celo ne zatareš!',
        12: 'Tudi vsi proroki so prorokovali tako in govorili: Pojdi proti Ramotu v Gileadu in srečno hodi, in Gospod ga da kralju v roko!',
        13: 'Sel pa, ki je šel poklicat Mihaja, mu govori in reče: Glej vendar: besede prorokov oznanjajo soglasno kralju dobro; bodi torej beseda tvoja kakor beseda enega izmed njih, in govóri dobro!',
        14: 'In Mihaj reče: Kakor res živi Gospod, kar mi poreče Gospod, bom govoril.',
        15: 'In ko pride h kralju, mu reče kralj: Mihaj, ali naj gremo v boj proti Ramotu v Gileadu ali naj opustimo? Odgovori: Pojdi in srečno hodi! Gospod ga da kralju v roko.',
        16: 'Kralj mu pa veli: Kolikokrat mi te je rotiti, da mi ne govoriš ničesar nego resnico v imenu Gospodovem?',
        17: 'In reče: Videl sem vse Izraelce razkropljene po gorah kakor ovce, ki nimajo pastirja; in Gospod je dejal: Ti nimajo gospodarja! Vsak naj se vrne domov v miru!',
        18: 'Nato reče kralj Izraelov Josafatu: Nisem ti li rekel, da mi ne prorokuje nič dobrega, nego zgolj hudo?',
        19: 'On reče: Zatorej čuj besedo Gospodovo! Videl sem Gospoda, da sedi na prestolu svojem, in vso vojsko nebeško, da mu stoji ob desnici in ob levici.',
        20: 'In Gospod je vprašal: Kdo premoti Ahaba, da bi šel gori in padel pri Ramotu v Gileadu? In ta je rekel to in drugi je rekel ono.',
        21: 'Tedaj pride duh in se postavi pred Gospoda in reče: Jaz ga premotim!',
        22: 'In Gospod ga vpraša: S čim? Odgovori: Pojdem tja in bodem lažniv duh v ustih vseh prorokov njegovih. In veli: Ti ga premotiš in se ti posreči. Pojdi tja in stóri tako!',
        23: 'Sedaj torej glej, Gospod je dal lažnivega duha v usta vseh teh prorokov tvojih, a Gospod je govoril hudo zoper tebe!',
        24: 'Tedaj pristopi Zedekija, sin Kenaanov, in udari Mihaja v lice in reče: Kod je šel duh Gospodov od mene, da s tabo govori?',
        25: 'Mihaj odvrne: Glej, videl boš tisti dan, ko boš hodil iz hrama v hram, da se skriješ!',
        26: 'Kralj Izraelov pa veli: Vzemi Mihaja in ga pelji nazaj k Amonu, mestnemu poglavarju, in k Joasu, sinu kraljevemu,',
        27: 'pa reci: Tako pravi kralj: Denita tega moža v ječo in živita ga s kruhom bridkosti in z vodo stiske, dokler se ne vrnem v miru!',
        28: 'A Mihaj reče: Ako se vrneš v miru, ni govoril po meni Gospod! Še reče: Čujte, vsi ljudje!',
        29: 'Nato sta šla kralj Izraelov in Josafat, kralj Judov, gori proti Ramotu v Gileadu.',
        30: 'In kralj Izraelov reče Josafatu: Jaz pojdem preoblečen v boj, ti pa obleci svoja oblačila! Preobleče se torej kralj Izraelov in gre v boj.',
        31: 'Kralj sirski pa je zapovedal dvaintridesetim poveljnikom svojih voz, rekoč: Ne bojujte se zoper male, ne zoper velike, ampak zgolj zoper kralja Izraelovega!',
        32: 'Ko torej vidijo poveljniki vozov Josafata, reko: Gotovo je on kralj Izraelov! In zaženo se bojevat zoper njega; in zavpije Josafat.',
        33: 'Ko pa vidijo poveljniki voz, da ni kralj Izraelov, se obrnejo od njega.',
        34: 'Neki mož pa slučajno napne lok in ustreli kralja Izraelovega med stike v oklepu. Tedaj veli svojemu vozniku: Obrni voz in pelji me z bojišča, kajti hudo sem ranjen.',
        35: 'A bitka se je razvnela tisti dan, in kralj je moral stati na vozu Sircem nasproti, in zvečer je umrl; in kri je tekla iz rane na dno voza.',
        36: 'In ko je solnce zahajalo, je šel klic po taborišču: Vsak pojdi v mesto svoje in v kraj svoj,',
        37: 'ker kralj je mrtev! In pripeljali so ga v Samarijo in pokopali v Samariji.',
        38: 'In ko so omivali voz pri samarijskem ribniku, so lizali psi kri njegovo in nečistnice so se omivale ž njo po besedi Gospodovi, ki jo je bil govoril.',
        39: 'In druge zgodbe Ahabove in vse, kar je storil, in slonokoščena hiša, ki jo je postavil, in vsa mesta, ki jih je sezidal, ni li zapisano v knjigi letopisov kraljev Izraelovih?',
        40: 'Tako je legel Ahab k očetom svojim, in Ahazija, sin njegov, je zakraljeval na mestu njegovem.',
        41: 'In Josafat, sin Asov, je zakraljeval nad Judom v četrtem letu Ahaba, kralja Izraelovega.',
        42: 'Josafat pa je bil petintrideset let star, ko je zakraljeval, in vladal je petindvajset let v Jeruzalemu. In materi njegovi je bilo ime Azuba, hči Silhijeva.',
        43: 'In hodil je po vsej poti Asa, očeta svojega; ni se ganil od nje in je delal, kar je bilo prav v očeh Gospodovih.',
        44: 'Toda višave niso bile odpravljene, ljudstvo je še darovalo in žgalo kadilo na višavah.',
        45: 'In Josafat je imel mir s kraljem Izraelovim.',
        46: 'Druge pa zgodbe Josafatove in hrabrost njegova, ki jo je dokazal, in kako se je bojeval, ni li pisano v knjigi letopisov kraljev Judovih?',
        47: 'On je tudi spravil iz dežele ostanke nečistoti posvečenih moških, ki so preostali v dneh Asa, očeta njegovega.',
        48: 'V Edomu pa ni bilo kralja, namestnik je vladal.',
        49: 'In Josafat je napravil tarske ladje, ki naj bi šle v Ofir po zlato; a niso šle, ker so se razbile v Ezion-geberju.',
        50: 'Tedaj je rekel Ahazija, sin Ahabov, Josafatu: Peljejo naj se hlapci moji na ladjah s hlapci tvojimi! A Josafat ni hotel.',
        51: 'In Josafat je legel k očetom svojim, in pokopali so ga pri očetih njegovih v mestu Davida, očeta njegovega. In Joram, sin njegov, je zakraljeval na mestu njegovem.',
        52: 'Ahazija, sin Ahabov, je zakraljeval nad Izraelom v Samariji v sedemnajstem letu Josafata, kralja Judovega, in je vladal Izraelu dve leti',
        53: 'in delal, kar je bilo hudo v očeh Gospodovih, hodeč po poti očeta svojega in po poti matere svoje in po poti Jeroboama, sinu Nebatovega, ki je zapeljeval Izraela v greh. In služil je Baalu in se mu poklanjal in dražil v jezo Gospoda, Boga Izraelovega, po vsem, kakor je bil delal oče njegov.',
    },
}
